window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[309]={"id":"309","numero":309,"titre":"Tumeurs du poumon, primitives et secondaires","objectifs":[{"id":"309-1","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types histologiques des cancers broncho-pulmonaires","contenu":"<p>Le diagnostic positif d'un cancer du poumon repose sur l'<span class=\"kw-def\">histologie</span> : la classification anatomopathologique distingue deux grandes familles — les <span class=\"kw-def\">carcinomes bronchiques non à petites cellules (CNPC)</span> qui représentent <span class=\"kw-chiffre\">&gt; 80 %</span> des cancers du poumon, et les <span class=\"kw-def\">tumeurs neuro-endocrines (TNE)</span> dont le chef de file est le <span class=\"kw-def\">carcinome bronchique à petites cellules (CBPC)</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Comparatif des 4 grands sous-types</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Adénocarcinome (<span class=\"kw-chiffre\">45-50 %</span>)</th><th>Épidermoïde (<span class=\"kw-chiffre\">25 %</span>)</th><th>CBPC (<span class=\"kw-chiffre\">15 %</span>)</th><th>Carcinoïdes (&lt;<span class=\"kw-chiffre\"> 1 %</span>)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Terrain</td>\n            <td>Femme, non tabagique, asiatique ; peut compliquer une <span class=\"kw-etio\">FPI</span> ou TB séquellaire</td>\n            <td>Impact majeur du <span class=\"kw-etio\">tabac</span></td>\n            <td>Quasi exclusivement <span class=\"kw-etio\">fumeur</span> ; <span class=\"kw-alerte\">forte association aux syndromes paranéoplasiques</span></td>\n            <td><span class=\"kw-alerte\">PAS d'association au tabagisme</span> ❌</td>\n          </tr>\n          <tr>\n            <td>Localisation</td>\n            <td><span class=\"kw-imagerie\">Périphérie</span> du poumon le plus souvent</td>\n            <td><span class=\"kw-imagerie\">Proximale / centrale</span> (grosses bronches)</td>\n            <td><span class=\"kw-imagerie\">Proximale</span> ; masse <span class=\"kw-imagerie\">hiliaire</span> ou <span class=\"kw-imagerie\">médiastinale</span></td>\n            <td>Variable</td>\n          </tr>\n          <tr>\n            <td>Accès biopsique</td>\n            <td>Souvent inaccessible à la <span class=\"kw-imagerie\">fibroscopie</span> → <span class=\"kw-clinique\">ponction transpariétale sous scanner</span></td>\n            <td>Accessible à la <span class=\"kw-clinique\">fibroscopie bronchique</span></td>\n            <td>Fibroscopie + biopsies dirigées</td>\n            <td>Fibroscopie + DOTATOC</td>\n          </tr>\n          <tr>\n            <td>Histologie</td>\n            <td>Architecture <span class=\"kw-def\">glandulaire</span> ; glandes ou mucosécrétion</td>\n            <td>Ponts inter-cellulaires ; foyers de <span class=\"kw-def\">kératinisation</span> (globes cernés)</td>\n            <td>Petites cellules ; cytoplasme rare ; <span class=\"kw-chiffre\">≥ 10 mitoses / 2 mm²</span> (moy &gt; 60)</td>\n            <td>Typiques : <span class=\"kw-chiffre\">&lt; 2 mitoses / 2 mm²</span>, pas de nécrose ; atypiques : <span class=\"kw-chiffre\">2-10 mitoses</span> ± nécrose</td>\n          </tr>\n          <tr>\n            <td>Immunohistochimie ⭐</td>\n            <td><span class=\"kw-bio\">TTF1 +</span>, <span class=\"kw-bio\">p40 -</span> ; <span class=\"kw-bio\">CK7 +</span>, <span class=\"kw-bio\">CK20 -</span></td>\n            <td><span class=\"kw-bio\">p40 +</span>, <span class=\"kw-bio\">TTF1 -</span></td>\n            <td><span class=\"kw-bio\">CD56 +</span>, <span class=\"kw-bio\">chromogranine A +</span>, <span class=\"kw-bio\">synaptophysine +</span> ; <span class=\"kw-bio\">NSE</span> aspécifique ; majorité TTF1+ <em>(non spécifique)</em></td>\n            <td>Marqueurs neuro-endocrines + ; <span class=\"kw-bio\">Ki-67</span> bas (typique) à modéré (atypique)</td>\n          </tr>\n          <tr>\n            <td>Traitement</td>\n            <td><span class=\"kw-ttt\">Thérapie ciblée</span> possible si addiction oncogénique → <strong>chercher EGFR ++</strong></td>\n            <td>Pas de thérapie ciblée ; <span class=\"kw-ci\">pémétrexed contre-indiqué</span> (non répondeur) ; <span class=\"kw-ci\">bévacizumab contre-indiqué</span> (plus toxique)</td>\n            <td><span class=\"kw-ttt\">Chimiothérapie urgente</span> ± radiothérapie ; <span class=\"kw-alerte\">chirurgie exceptionnelle, jamais seule</span></td>\n            <td>Exérèse économe en parenchyme</td>\n          </tr>\n          <tr>\n            <td>Imagerie typique</td>\n            <td>Masse périphérique à contours <span class=\"kw-imagerie\">spiculés</span> ; peu de nécrose/cavitation</td>\n            <td>Bourgeon endoluminal ; <span class=\"kw-imagerie\">atélectasie segmentaire</span> ± pneumopathie obstructive d'amont</td>\n            <td>Masse hiliaire/médiastinale volumineuse ; <span class=\"kw-imagerie\">syndromes de compression</span></td>\n            <td>Calcification possible (utile au <span class=\"kw-imagerie\">TDM</span>)</td>\n          </tr>\n          <tr>\n            <td>Complications</td>\n            <td><span class=\"kw-alerte\">Métastases cérébrales</span> révélatrices ++</td>\n            <td><span class=\"kw-alerte\">Métastases osseuses</span> possibles</td>\n            <td><span class=\"kw-alerte\">Métastases d'emblée 70-75 %</span> (cérébrales ++)</td>\n            <td>Pronostic globalement bon</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Classification des adénocarcinomes (<span class=\"kw-chiffre\">≤ 3 cm</span>)</h4>\n      <ul>\n        <li><span class=\"kw-def\">Hyperplasie adénomateuse atypique</span> et <span class=\"kw-def\">adénocarcinome in situ</span> (AIS) : lésions pré-invasives ; croissance lépidique le long des parois alvéolaires ; bronchorrée si mucineux ; <span class=\"kw-imagerie\">TDM</span> en <span class=\"kw-imagerie\">verre dépoli pur</span> <span class=\"kw-chiffre\">≤ 3 cm</span> ; pas d'invasion → bon pronostic.</li>\n        <li><span class=\"kw-def\">Adénocarcinome avec invasion minime</span> : verre dépoli <span class=\"kw-chiffre\">≤ 3 cm</span> avec composant solide <span class=\"kw-chiffre\">&lt; 5 mm</span>.</li>\n        <li><span class=\"kw-def\">Adénocarcinome invasif</span> : zone solide <span class=\"kw-chiffre\">&gt; 5 mm</span> ; sous-types lépidique / acinaire / papillaire / micro-papillaire / solide. <span class=\"kw-alerte\">Micro-papillaire et solide = mauvais pronostic.</span></li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cas particuliers</h4>\n      <ul>\n        <li><span class=\"kw-def\">Carcinome à grandes cellules</span> : appellation réservée aux pièces opératoires suffisamment échantillonnées ; sur biopsie on parle de <span class=\"kw-def\">NSCLC-NOS</span> <em>(non small cell lung cancer - not otherwise specified)</em>. Si TTF1+/p40- → CNPC en faveur d'un adénocarcinome ; si p40+/TTF1- → en faveur d'un épidermoïde ; tous positifs → adéno-squameux ; tous négatifs → carcinome à grandes cellules.</li>\n        <li><span class=\"kw-def\">Carcinome neuro-endocrine à grandes cellules</span> (<span class=\"kw-chiffre\">1-2 %</span>) : morphologie neuro-endocrine + cellules de grande taille + nécrose étendue + Ki-67 <span class=\"kw-chiffre\">40-80 %</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Pas de continuum évolutif entre tumeurs carcinoïdes et TNE de haut grade (CBPC, neuro-endocrine à grandes cellules). Le diagnostic des TNE repose sur <span class=\"kw-bio\">compte des mitoses</span> + <span class=\"kw-bio\">index Ki-67</span>.\n      </div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/lung-cancer-3","label":"Radiopaedia : Lung cancer 3"}]},{"id":"309-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie descriptive","contenu":"<p>Le cancer du poumon est, en 2018, le <strong>1ᵉʳ cancer diagnostiqué dans le monde</strong> avec <span class=\"kw-chiffre\">2,1 millions</span> de nouveaux cas par an. L'incidence et la mortalité restent élevées dans les <span class=\"kw-etio\">pays à forte consommation de tabac</span> (Chine) et diminuent là où les campagnes anti-tabac sont anciennes (USA, Grande-Bretagne).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Chiffres clés</h4>\n      <table >\n        <thead>\n          <tr><th>Indicateur</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Incidence France</td><td><span class=\"kw-chiffre\">46 000</span> nouveaux cas/an</td></tr>\n          <tr><td>Rang chez l'homme</td><td><span class=\"kw-chiffre\">2ᵉ</span> cancer solide (après prostate)</td></tr>\n          <tr><td>Rang chez la femme</td><td><span class=\"kw-chiffre\">3ᵉ</span> cancer solide (après sein et côlon-rectum)</td></tr>\n          <tr><td>Rang tous sexes</td><td><span class=\"kw-chiffre\">3ᵉ</span> cancer solide (après sein et prostate)</td></tr>\n          <tr><td>Prévalence France (2017)</td><td><span class=\"kw-chiffre\">170 000</span> personnes</td></tr>\n          <tr><td>Mortalité France</td><td><span class=\"kw-chiffre\">33 000</span> décès/an — <span class=\"kw-alerte\">1ʳᵉ cause de mortalité par cancer</span> (<span class=\"kw-chiffre\">20 %</span> des décès par cancer)</td></tr>\n          <tr><td>Mortalité homme</td><td><span class=\"kw-alerte\">1ʳᵉ cause</span> de décès par cancer</td></tr>\n          <tr><td>Mortalité femme</td><td><span class=\"kw-alerte\">2ᵉ cause</span> de décès par cancer (après le sein)</td></tr>\n          <tr><td>Mortalité monde</td><td><span class=\"kw-chiffre\">1,8 million</span> décès/an — 1ʳᵉ cause de mortalité par cancer (H et F)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Tendances et démographie</h4>\n      <ul>\n        <li>Maladie encore <strong>majoritairement masculine</strong> : <span class=\"kw-chiffre\">67 %</span> des cas incidents, <span class=\"kw-chiffre\">69 %</span> des décès.</li>\n        <li>Homme : incidence en diminution lente (<span class=\"kw-chiffre\">- 0,3 % / an</span> entre 2010 et 2018), mortalité en diminution. ⭐</li>\n        <li>Femme : <span class=\"kw-alerte\">incidence en augmentation forte (+ 5 % / an)</span> ⚠️ — reflet décalé de la diffusion du tabagisme féminin.</li>\n        <li>Âge médian au diagnostic : <span class=\"kw-chiffre\">67 ans</span> chez l'homme, <span class=\"kw-chiffre\">65 ans</span> chez la femme.</li>\n        <li>Survie tous stades à <span class=\"kw-chiffre\">5 ans : 17 %</span>. Amélioration récente liée aux thérapies ciblées et à l'immunothérapie.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège fréquent.</strong> Le décalage hommes/femmes (diminution chez l'homme, augmentation chez la femme) suit la diffusion du tabagisme : la mortalité féminine devrait rattraper celle de l'homme dans les décennies à venir.\n      </div>","frequence":0},{"id":"309-3","rang":"A","rubrique":"Etiologie","titre":"Connaître les principaux facteurs de risque professionnels et environnementaux","contenu":"<p>Le <span class=\"kw-etio\">tabac</span> est le facteur de risque dominant (<span class=\"kw-chiffre\">1ᵉʳ FdR évitable de mortalité précoce par cancer</span> en France et dans le monde) : <span class=\"kw-chiffre\">75 000</span> décès annuels liés au tabac, <span class=\"kw-chiffre\">46 500</span> décès par cancer liés au tabac, <span class=\"kw-chiffre\">25 %</span> des cancers sont liés au tabac. <span class=\"kw-alerte\">Pas de seuil de consommation sans risque ; le tabagisme passif augmente aussi le risque.</span></p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Tabac et cancer du poumon</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>Proportion de CP liés au tabac</td><td><span class=\"kw-chiffre\">90 %</span> des cas — <span class=\"kw-chiffre\">80 %</span> des décès</td></tr>\n          <tr><td>Risque relatif (tabagisme actif)</td><td>× <span class=\"kw-chiffre\">2 à 30</span> selon l'exposition</td></tr>\n          <tr><td>Tabagisme passif</td><td>+ <span class=\"kw-chiffre\">25 %</span> de risque ; responsable de <span class=\"kw-chiffre\">25 %</span> des CP du non-fumeur</td></tr>\n          <tr><td>Facteur le plus important</td><td><strong>Durée du tabagisme</strong> &gt; nombre de cigarettes/jour</td></tr>\n          <tr><td>Effet de l'arrêt</td><td><span class=\"kw-alerte\">Risque décroît mais ne revient JAMAIS à celui du non-fumeur</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Agents cancérogènes professionnels (CIRC)</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Agents</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cancérogènes certains</strong></td>\n            <td>\n              <span class=\"kw-etio\">Amiante</span> ; <span class=\"kw-etio\">arsenic</span> ; <span class=\"kw-etio\">bis(chlorométhyl)éther</span> ; <span class=\"kw-etio\">fumées de cadmium</span> ; <span class=\"kw-etio\">chrome hexavalent</span> ; <span class=\"kw-etio\">HAP</span> (hydrocarbures aromatiques polycycliques) ; <span class=\"kw-etio\">nickel</span> ; <span class=\"kw-etio\">silice cristalline</span> (à condition d'être associée à une silicose radiologique) ; <span class=\"kw-etio\">radiations ionisantes</span> (radon professionnel)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cancérogènes potentiels</strong></td>\n            <td><span class=\"kw-etio\">Cobalt associé au carbure de tungstène</span> ; travaux au fond des <span class=\"kw-etio\">mines de fer</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Synthèse FdR par catégorie</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Tabac</strong></td>\n            <td>\n              <strong>Actif :</strong> responsable de <span class=\"kw-chiffre\">85 %</span> des cancers du poumon<br>\n              <strong>Passif :</strong> responsable de <span class=\"kw-chiffre\">25 %</span> des CP des non-fumeurs<br>\n              <strong>Risque dès la 1ʳᵉ cigarette :</strong> pas de seuil\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Carcinogènes professionnels</strong></td>\n            <td>\n              <strong>Prévalence :</strong> exposition retrouvée dans <span class=\"kw-chiffre\">20 %</span> des CP (<span class=\"kw-chiffre\">11 %</span> chez l'homme, <span class=\"kw-chiffre\">4 %</span> chez la femme)<br>\n              <strong>Bâtiment :</strong> amiante ++<br>\n              <strong>Métaux :</strong> arsenic ; cadmium ; chrome ; nickel ; cobalt + W<br>\n              <strong>Autres listés par le CIRC (hors tableaux) :</strong> béryllium ; peinture ; industrie du caoutchouc ; <span class=\"kw-etio\">fumées d'échappement diesel</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pollution atmosphérique</strong></td>\n            <td>\n              Rôle cancérigène pour le poumon reconnu<br>\n              <strong>Gaz :</strong> <span class=\"kw-etio\">SO₂, NO₂, NOₓ, O₃</span><br>\n              <strong>Particules fines :</strong> émises par les véhicules <span class=\"kw-etio\">diesel</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Radon (exposition domestique)</strong></td>\n            <td>\n              <strong>Proportion :</strong> <span class=\"kw-chiffre\">5-10 %</span> des CP<br>\n              <strong>Origine :</strong> gaz radioactif incolore et inodore, émis par les <span class=\"kw-etio\">sous-sols granitiques et volcaniques</span> (Bretagne, centre, Vosges, Alpes, Corse)<br>\n              <strong>Seuil OMS :</strong> <span class=\"kw-chiffre\">300 Bq/m³</span> (France &lt; 100 Bq/m³ en moyenne)<br>\n              <strong>Prévention :</strong> aération du logement <span class=\"kw-chiffre\">≥ 10 min</span>/j ; étanchéité des bâtiments\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Diététique</strong></td>\n            <td>\n              Faible consommation de fruits/légumes ; forte consommation de viande ; <span class=\"kw-etio\">surpoids</span> ; sédentarité<br>\n              <strong>Protecteur :</strong> activité physique régulière\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FdR individuels</strong></td>\n            <td>\n              <strong>Pathologies respiratoires (sur-risque indépendant du tabac) :</strong> <span class=\"kw-etio\">BPCO</span> ; <span class=\"kw-etio\">PID fibrosantes</span> ; pneumonie ; tuberculose<br>\n              <strong>ATCD personnel de CP :</strong> risque accru de 2ⁿᵈ cancer (surtout si poursuite du tabac)<br>\n              <strong>ATCD familial :</strong> risque accru si parenté au <span class=\"kw-chiffre\">1ᵉʳ degré</span><br>\n              <strong>Susceptibilité génétique :</strong> loci <span class=\"kw-bio\">15q, 5p, 6p</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Les mutations somatiques <span class=\"kw-bio\">EGFR</span>, <span class=\"kw-bio\">KRAS</span> et autres ne sont <strong>pas</strong> des anomalies constitutionnelles : elles n'existent que dans les cellules cancéreuses, pas dans le génome germinal de l'individu. Ce ne sont donc pas des FdR héréditaires.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir — addiction oncogénique.</strong> Présence d'<strong>une seule</strong> mutation driver (EGFR, BRAF, MET exon 14, HER2, ALK, NTRK, ROS1) : prédictive de la réponse aux <span class=\"kw-ttt\">ITK</span>. Survient surtout chez : <span class=\"kw-clinique\">non-fumeurs</span> (jamais fumé ou sevrés &gt;<span class=\"kw-chiffre\"> 10 ans</span>), <span class=\"kw-clinique\">adénocarcinomes</span>, <span class=\"kw-clinique\">femmes</span>, patients d'origine <span class=\"kw-clinique\">asiatique</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction Tabac · 182 — Environnement professionnel, sécurité au travail · 184 — Accident - maladie professionnel · 210 — Pneumopathie interstitielle diffuse</em></p>","frequence":5},{"id":"309-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances de découvertes et les manifestations cliniques des tumeurs du poumon (y compris syndromes para-néoplasiques)","contenu":"<p>Environ <span class=\"kw-chiffre\">¾</span> des cancers du poumon sont diagnostiqués à un stade <span class=\"kw-alerte\">localement avancé ou métastatique</span>. Au diagnostic : <span class=\"kw-chiffre\">40 %</span> sont localisés au thorax, <span class=\"kw-chiffre\">60 %</span> sont métastatiques. Trois facteurs expliquent ce retard : absence d'<strong>innervation nociceptive</strong> bronchopulmonaire (pas de douleur), symptômes tardifs (atteinte d'organes centraux/périphériques ou métastases), symptômes non spécifiques.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'<span class=\"kw-alerte\">absence de FdR n'exclut PAS</span> le diagnostic de cancer du poumon.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Circonstances de découverte</h4>\n      <table >\n        <thead><tr><th>Cadre</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Dépistage</strong></td>\n            <td>\n              <strong>Non recommandé en France</strong> à ce jour. Modalité validée : <span class=\"kw-imagerie\">TDM thoracique low-dose sans injection</span> (jamais la <span class=\"kw-imagerie\">RXT</span> ❌)<br>\n              <strong>Cible :</strong> <span class=\"kw-clinique\">50-75 ans, fumeur ≥ 30 PA</span> (≥ 15 cig/j <span class=\"kw-chiffre\">≥ 25 ans</span> ou ≥ 20 cig/j <span class=\"kw-chiffre\">≥ 30 ans</span>), éventuellement sevrés &lt;<span class=\"kw-chiffre\"> 15 ans</span><br>\n              <strong>Rythme :</strong> tous les <span class=\"kw-chiffre\">1 à 2 ans</span><br>\n              <strong>Bénéfice :</strong> ↓ mortalité par cancer de <span class=\"kw-chiffre\">20-25 %</span>, mortalité globale de <span class=\"kw-chiffre\">7 %</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes généraux</strong></td>\n            <td><span class=\"kw-clinique\">AEG</span> inexpliquée : asthénie, anorexie, amaigrissement</td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes respiratoires</strong></td>\n            <td>\n              <strong>Toux :</strong> récente ou modification d'une toux ancienne — souvent révélatrice mais négligée par les fumeurs<br>\n              <strong>Dyspnée :</strong> inexpliquée ou progressive<br>\n              <strong>Hémoptysie :</strong> généralement de faible abondance<br>\n              <strong>Expectoration purulente :</strong> infection en aval d'une sténose ou nécrose tumorale<br>\n              <strong>Pneumopathie / abcès récidivant dans un même territoire</strong> régressant mal aux antibiotiques\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Extension loco-régionale</strong><br><em>(élimine d'emblée le recours chirurgical, sauf parfois pariétal)</em></td>\n            <td>\n              <strong>Douleur thoracique :</strong> envahissement pariétal<br>\n              <strong>Épanchement pleural :</strong> séro-fibrineux ou séro-hémorragique ; confirmation néoplasique par cellules dans le liquide ou biopsie pleurale<br>\n              <strong>Syndrome de Pancoast-Tobias :</strong> plexopathie infiltrative par tumeur de l'<span class=\"kw-imagerie\">apex pulmonaire</span><br>\n              <strong>Syndrome médiastinal :</strong> <span class=\"kw-alerte\">syndrome cave supérieur</span> ; <span class=\"kw-clinique\">dysphonie</span> (compression du nerf récurrent gauche) ; <span class=\"kw-clinique\">dysphagie</span> (compression œsophagienne) ; <span class=\"kw-clinique\">hoquet, paralysie phrénique</span> (ascension de coupole en <span class=\"kw-imagerie\">RXT</span>) ; <span class=\"kw-alerte\">péricardite avec tamponnade</span> ou arythmie récente\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ganglions</strong></td>\n            <td>Examen clinique systématique : aires <span class=\"kw-clinique\">axillaires</span>, <span class=\"kw-clinique\">sus-claviculaires</span>, <span class=\"kw-clinique\">cervicales</span></td>\n          </tr>\n          <tr>\n            <td><strong>Métastases</strong></td>\n            <td>\n              <strong>SNC :</strong> <span class=\"kw-alerte\">convulsions</span>, signes de focalisation, <span class=\"kw-alerte\">HTIC</span>, compression médullaire, syndrome de la queue de cheval<br>\n              <strong>Os :</strong> douleur, fracture pathologique, tassement vertébral, <span class=\"kw-bio\">hypercalcémie</span><br>\n              <strong>Foie :</strong> hépatomégalie, hépatalgies, perturbations du bilan biologique<br>\n              <strong>Surrénales :</strong> fréquentes, habituellement asymptomatiques<br>\n              <strong>Plus rares :</strong> ganglionnaires superficielles ; cutanées (nodules sous-cutanés) ; péritonéales ; méningées\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Syndromes paranéoplasiques ⭐⭐⭐⭐⭐⭐</h4>\n      <p>Manifestations liées à la <span class=\"kw-def\">sécrétion d'hormones ou neuromédiateurs</span> par la tumeur, ou à la réaction immunitaire (auto-anticorps). Quatre catégories à connaître : <strong>communs</strong>, <strong>évocateurs d'un CNPC</strong>, <strong>évocateurs d'un CBPC</strong>, et la règle de rechute.</p>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Communs</strong></td>\n            <td>\n              <strong>Fièvre :</strong> au long cours, inexpliquée<br>\n              <strong>Syndromes hématologiques :</strong> anémie ; hyperleucocytose ; thrombocytose<br>\n              <strong>MTEV non provoquée :</strong> <span class=\"kw-alerte\">souvent extensive et/ou de localisation inhabituelle</span> ; résistant parfois au traitement anticoagulant\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Évocateurs d'un cancer NON à petites cellules (CNPC)</strong></td>\n            <td>\n              <strong>Hippocratisme digital :</strong> phalange distale en baguettes de tambour ; bombement des ongles dorsaux ; hypertrophie phalangienne distale<br>\n              <strong>OAHP (Pierre-Marie-Bamberger) :</strong> hippocratisme + arthralgies distales <span class=\"kw-clinique\">œdémateuses</span> ; périostose engainante « coulée de bougie » aux os longs<br>\n              <strong>Dermato-polymyosite :</strong> rash héliotrope ; faiblesse musculaire proximale<br>\n              <strong>Hypercalcémie :</strong> sécrétion d'un peptide <span class=\"kw-bio\">PTH-like</span> ; à distinguer des métastases osseuses (plus fréquentes)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Évocateurs d'un cancer à petites cellules (CBPC)</strong></td>\n            <td>\n              <strong>Syndrome de Schwartz-Bartter (SIADH) :</strong> <span class=\"kw-bio\">hyponatrémie</span> avec natriurèse conservée<br>\n              <strong>Syndrome de Cushing :</strong> sécrétion ectopique d'<span class=\"kw-bio\">ACTH-like</span><br>\n              <strong>Gynécomastie</strong><br>\n              <strong>Syndromes neurologiques auto-immuns :</strong> pseudo-myasthénie de Lambert-Eaton ; neuropathie sensitive subaiguë de Denny-Brown ; encéphalopathie paranéoplasique (<span class=\"kw-bio\">anti-Hu</span>) avec dégénérescence cérébelleuse\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Urgence diagnostique.</strong> Après résection complète, la <strong>réapparition</strong> d'un syndrome paranéoplasique traduit une <span class=\"kw-alerte\">rechute tumorale</span> jusqu'à preuve du contraire.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Iconographie clinique et radiologique</h4>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/309/hippocratisme-digital.jpg\" alt=\"Hippocratisme digital — déformation des phalanges distales en baguettes de tambour, bombement des ongles dorsaux\">\n        <figcaption><strong>Hippocratisme digital.</strong> Déformation des doigts et des ongles : <span class=\"kw-clinique\">bombement des ongles</span> sur la face dorsale + <span class=\"kw-clinique\">hypertrophie phalangienne distale</span> (« baguettes de tambour »). Recherche systématique d'une cause respiratoire : <strong>cancer broncho-pulmonaire</strong> (souvent associé à l'OAHP de Pierre-Marie), dilatation des bronches, fibrose pulmonaire. Causes extra-respiratoires : endocardite, cardiopathie cyanogène, MICI (Crohn, RCH), hépatite/cirrhose chronique, cancer digestif.</figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/309/oahp-periostose-coulee-bougie.png\" alt=\"Périostose engainante en coulée de bougie sur la corticale des os longs — OAHP de Pierre-Marie-Bamberger\">\n        <figcaption><strong>Périostose engainante « coulée de bougie » (OAHP).</strong> <span class=\"kw-imagerie\">Liseré radio-opaque doublant la corticale des os longs</span>, <span class=\"kw-alerte\">à ne pas confondre avec des métastases osseuses</span>. Composante du syndrome de Pierre-Marie-Bamberger : hippocratisme digital + arthralgies distales œdémateuses + périostite engainante. Évoque plutôt un cancer du poumon <strong>NON à petites cellules</strong>.</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 203 — Dyspnée · 205 — Hémoptysie · 206 — Epanchement pleural · 226 — Thrombose veineuse profonde - EP · 267 — Trouble de l'équilibre acido-basique - Désordre hydro-électrolytique · 268 — Hypercalcémie · 154 — Infection bronchopulmonaire communautaire · 359 — Détresse et insuffisance respiratoire aiguë</em></p>","frequence":6,"liens":[{"href":"https://radiopaedia.org/articles/hypertrophic-osteoarthropathy","label":"Radiopaedia : Hypertrophic osteoarthropathy"}]},{"id":"309-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique devant une tumeur du poumon","contenu":"<p>La démarche diagnostique part d'une <span class=\"kw-clinique\">suspicion clinico-radiologique</span> (toux récente, hémoptysie, AEG chez un fumeur ; nodule fortuit) et s'organise en 3 temps : <strong>imagerie d'orientation</strong> (<span class=\"kw-imagerie\">TDM</span> thoracique injectée) → <strong>choix de la technique biopsique</strong> selon la localisation → <strong>preuve histologique</strong> (gold standard).</p>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le diagnostic positif repose sur l'<span class=\"kw-def\">histologie</span> ✅. La <span class=\"kw-alerte\">cytologie n'est PAS un standard</span> ❌ — elle ne permet pas un typage complet, un bilan moléculaire fiable ni l'établissement de l'immunohistochimie complète.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étape 1 — Orientation bénin / malin sur nodule pulmonaire solide</h4>\n      <table >\n        <thead><tr><th>Critère</th><th>Faible risque</th><th>Haut risque</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              Jeune âge ; non ou faiblement fumeur<br>\n              <span class=\"kw-clinique\">Asymptomatique</span>\n            </td>\n            <td>\n              Homme, <span class=\"kw-chiffre\">&gt; 50 ans</span>, fumeur, ATCD de cancer<br>\n              <span class=\"kw-clinique\">Hémoptysie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span></strong></td>\n            <td>\n              Petite taille (<span class=\"kw-chiffre\">&lt; 1 cm</span>) ; contours réguliers ; hors lobes supérieurs<br>\n              <span class=\"kw-imagerie\">Calcifications</span> : entièrement calcifié ; centrale orthogonale ; périphérique ; lamellaire\n            </td>\n            <td>\n              Taille <span class=\"kw-chiffre\">&gt; 1 cm</span> ; contours <span class=\"kw-imagerie\">irréguliers, spiculés</span><br>\n              Attire les structures de voisinage<br>\n              <span class=\"kw-alerte\">Localisation lobaire supérieure ⚠️</span><br>\n              Non calcifié ; <span class=\"kw-imagerie\">prise de contraste</span> en <span class=\"kw-imagerie\">TDM</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Évolution <span class=\"kw-imagerie\">TDM</span></strong></td>\n            <td>\n              Disparition ou quasi-disparition<br>\n              Diminution persistante<br>\n              Absence d'évolution à <span class=\"kw-chiffre\">2 ans</span> (solides)<br>\n              Absence d'évolution à <span class=\"kw-chiffre\">3-5 ans</span> (verre dépoli)\n            </td>\n            <td><span class=\"kw-alerte\">Progression rapide</span> en taille ou volume</td>\n          </tr>\n          <tr>\n            <td><strong>TEP-FDG</strong></td>\n            <td>Fixation faible</td>\n            <td>Fixation élevée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège fréquent.</strong> Aucun argument clinico-radiologique n'est formel — seule l'<span class=\"kw-def\">histologie</span> permet un diagnostic de certitude. Les <span class=\"kw-imagerie\">tumeurs carcinoïdes bronchiques</span> peuvent se calcifier (calcifications possibles dans le « bon » groupe radiologique).\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étape 2 — Choix de la technique biopsique</h4>\n      <table >\n        <thead><tr><th>Localisation</th><th>Technique privilégiée</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Systématique en cas de suspicion de CP ⭐</strong></td><td><span class=\"kw-clinique\">Fibroscopie bronchique</span> (sauf hypoxémie réfractaire ou anomalies majeures de coagulation)</td></tr>\n          <tr><td>Lésion centrale (1/3 péri-carénaire)</td><td>Fibroscopie bronchique</td></tr>\n          <tr>\n            <td>Lésion périphérique (1/3 périphérique)</td>\n            <td>\n              <strong>Ponction transpariétale</strong> (sous <span class=\"kw-imagerie\">TDM</span> ± écho-guidée)<br>\n              <strong>Vidéo-thoracoscopie exploratrice</strong> en alternative\n            </td>\n          </tr>\n          <tr>\n            <td>Entre les deux</td>\n            <td>\n              Fibroscopie bronchique<br>\n              Ponction transpariétale<br>\n              Thoracotomie exploratrice\n            </td>\n          </tr>\n          <tr>\n            <td>Adénopathies au contact de la trachée</td>\n            <td>\n              <span class=\"kw-clinique\">EBUS</span> (<span class=\"kw-imagerie\">fibroscopie</span> + aiguille)<br>\n              Écho-endoscopie œsophagienne (<span class=\"kw-clinique\">EUS</span>)<br>\n              <span class=\"kw-clinique\">Médiastinoscopie</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span class=\"kw-imagerie\">fibroscopie bronchique</span> reste indiquée même dans les cancers périphériques (peut être normale, n'élimine pas le diagnostic) : elle recherche les lésions radio-occultes proximales et oriente d'éventuelles biopsies systématiques (éperon, carène).\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étape 3 — Bilan d'extension à distance (cTNM)</h4>\n      <p>Une fois le diagnostic histologique posé, le bilan d'extension cherche à compléter le <span class=\"kw-def\">cTNM</span> (T loco-régional, N ganglionnaire, M métastatique) pour orienter la stratégie thérapeutique.</p>\n\n      <table >\n        <thead><tr><th>Modalité</th><th>Indication</th><th>Cible / Limites</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> TAP injectée</strong></td>\n            <td>Systématique chez tous les patients</td>\n            <td>\n              <strong>T :</strong> extension loco-régionale<br>\n              <strong>N :</strong> adénopathies médiastinales (taille)<br>\n              <strong>M :</strong> <span class=\"kw-imagerie\">foie, surrénales, ganglions abdominaux, lésions osseuses</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> cérébrale ou <span class=\"kw-imagerie\">IRM cérébrale</span></strong></td>\n            <td>Systématique (CNPC et CBPC)</td>\n            <td>\n              <span class=\"kw-imagerie\">Métastases cérébrales</span> souvent prévalentes et asymptomatiques<br>\n              <strong><span class=\"kw-imagerie\">IRM</span> préférable</strong> : sensibilité supérieure à la <span class=\"kw-imagerie\">TDM</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TEP-TDM</span> au <span class=\"kw-chiffre\">¹⁸F-FDG</span></strong></td>\n            <td>\n              <span class=\"kw-alerte\">Uniquement si la tumeur est a priori éligible à un traitement local</span> (chirurgie ou radiothérapie)<br>\n              Donc <strong>pas en 1ʳᵉ intention</strong> ; non recommandé si métastases déjà visibles au <span class=\"kw-imagerie\">TDM</span>\n            </td>\n            <td>\n              <strong>N :</strong> staging médiastinal (hyperfixation d'adénopathie de taille normale)<br>\n              <strong>M :</strong> détection de métastases à distance (bonne VPN)<br>\n              <span class=\"kw-alerte\">Pièges :</span> faux négatifs si nodule &lt;<span class=\"kw-chiffre\"> 1 cm</span> ou verre dépoli pur ; faux positifs sur infections chroniques, mycobactérioses, sarcoïdose\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Confirmation anatomopathologique du N</strong></td>\n            <td>Si modification thérapeutique attendue selon le staging N</td>\n            <td>\n              <span class=\"kw-clinique\">Écho-endoscopie bronchique (EBUS)</span> en 1ʳᵉ intention<br>\n              ou <span class=\"kw-clinique\">EUS</span> / médiastinoscopie selon le site\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège ⚠️.</strong> Le <span class=\"kw-def\">TEP-TDM n'est PAS recommandé</span> en cas de tumeur d'emblée métastatique sur le <span class=\"kw-imagerie\">TDM</span> initial — sa place se justifie uniquement quand un traitement local est encore envisageable.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Classification ganglionnaire N (extension TNM)</h4>\n      <table >\n        <thead><tr><th>Stade N</th><th>Territoire ganglionnaire envahi</th></tr></thead>\n        <tbody>\n          <tr><td><strong>N0</strong></td><td>Absence d'adénopathie</td></tr>\n          <tr><td><strong>N1</strong></td><td>Site <span class=\"kw-imagerie\">hiliaire</span> (homolatéral) envahi</td></tr>\n          <tr><td><strong>N2</strong></td><td>Site <span class=\"kw-imagerie\">médiastinal homolatéral</span> et/ou <span class=\"kw-imagerie\">sous-carinaire</span> envahi</td></tr>\n          <tr><td><strong>N3</strong></td><td>Site <span class=\"kw-alerte\">médiastinal controlatéral</span> et/ou <span class=\"kw-alerte\">sus-claviculaire</span> envahi</td></tr>\n        </tbody>\n      </table>\n      <p>Le <strong>T</strong> (extension loco-régionale) s'évalue par <span class=\"kw-imagerie\">TDM</span> thoracique + <span class=\"kw-imagerie\">bronchoscopie</span> ; le <strong>N</strong> par la <span class=\"kw-imagerie\">TDM</span> complétée par la <span class=\"kw-imagerie\">TEP-TDM</span>, avec preuve anatomopathologique par <span class=\"kw-clinique\">écho-endoscopie bronchique (EBUS)</span> en 1ʳᵉ intention si besoin ; le <strong>M</strong> est coté M0 ou M1.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>cTNM vs pTNM.</strong> Le <span class=\"kw-def\">cTNM</span> (« clinique ») est établi sur la clinique et la paraclinique au moment du bilan ; le <span class=\"kw-def\">pTNM</span> (« pathology ») est défini en <strong>post-opératoire</strong>, une fois le T et le N expertisés sur la pièce d'exérèse et le curage ganglionnaire. Le CBPC est classé selon la <strong>même TNM</strong> que les CNPC.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 293 — Anapath</em></p>","frequence":3},{"id":"309-6","rang":"B","rubrique":"Définition","titre":"Connaître les particularités du cancer à petites cellules","contenu":"<p>Le <span class=\"kw-def\">cancer bronchique à petites cellules (CBPC)</span> représente <span class=\"kw-chiffre\">15 %</span> des cancers du poumon. C'est une <span class=\"kw-def\">tumeur neuro-endocrine de haut grade</span> de pronostic redoutable, à séparer absolument des CNPC sur le plan thérapeutique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Caractéristiques clés</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Particularité</th></tr></thead>\n        <tbody>\n          <tr><td>Proportion</td><td><span class=\"kw-chiffre\">15 %</span> des cancers du poumon</td></tr>\n          <tr>\n            <td><strong>Localisation</strong></td>\n            <td>Habituellement <span class=\"kw-imagerie\">proximale</span> (voies aériennes proximales, masse <span class=\"kw-imagerie\">hiliaire</span> ou <span class=\"kw-imagerie\">médiastinale</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Pourquoi mauvais pronostic ?</strong></td>\n            <td>\n              <strong>Extension loco-régionale précoce :</strong> lymphatique, ganglionnaire, vasculaire<br>\n              <strong>Tumeurs volumineuses mal limitées :</strong> syndromes de compression<br>\n              <strong>Métastases précoces et quasi-constantes :</strong> <span class=\"kw-chiffre\">70-75 %</span> au diagnostic<br>\n              <strong>Association fréquente :</strong> <span class=\"kw-alerte\">syndromes paranéoplasiques</span><br>\n              <strong>Index mitotique élevé :</strong> <span class=\"kw-chiffre\">≥ 10 mitoses / 2 mm²</span> (moy &gt; 60)<br>\n              <strong>Index de prolifération élevé :</strong> <span class=\"kw-bio\">Ki-67 ≥ 80 %</span> en moyenne\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Chimiosensibilité</strong></td>\n            <td>Grande chimiosensibilité initiale, MAIS <span class=\"kw-alerte\">risque élevé de rechute précoce</span> (notamment <span class=\"kw-imagerie\">cérébrale</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Marqueurs IHC</strong></td>\n            <td>\n              <strong>Marqueurs neuro-endocrines :</strong> <span class=\"kw-bio\">CD56 (N-CAM)</span> ; <span class=\"kw-bio\">chromogranine A</span> ; <span class=\"kw-bio\">synaptophysine</span><br>\n              <strong>NSE :</strong> positive mais <em>aspécifique</em><br>\n              <strong>TTF1 :</strong> exprimé dans la majorité des CBPC, mais <em>non spécifique</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bilan d'extension</strong></td>\n            <td>Classification <span class=\"kw-def\">TNM identique aux CNPC</span> ; pas de système séparé. Distinction pratique : <strong>formes limitées</strong> vs <strong>formes diffuses</strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Pas de continuum évolutif entre <span class=\"kw-def\">tumeurs carcinoïdes</span> (TNE de bas grade) et <span class=\"kw-def\">CBPC / carcinome neuro-endocrine à grandes cellules</span> (TNE de haut grade). Les carcinoïdes ne sont <strong>pas</strong> les précurseurs des TNE de haut grade.\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Urgence.</strong> Sans traitement, le CBPC entraîne le décès en <span class=\"kw-chiffre\">&lt; 3 mois</span> (temps de doublement cellulaire très court). La chimiothérapie est donc une <span class=\"kw-alerte\">urgence oncologique</span> à instaurer le plus précocement possible.\n      </div>","frequence":0},{"id":"309-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens d’imagerie et leurs indications dans l’exploration d’une tumeur primitive du poumon","contenu":"<p>L'imagerie a deux rôles : <strong>orienter le diagnostic</strong> (caractérisation d'un nodule, repérage pour biopsie) et <strong>bilan d'extension</strong> (<span class=\"kw-def\">cTNM</span>). Quatre modalités à connaître : <span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-imagerie\">TDM injectée</span>, <span class=\"kw-imagerie\">TEP-FDG</span>, <span class=\"kw-imagerie\">DOTATOC</span>. Aucune ne remplace l'<span class=\"kw-def\">histologie</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Comparatif des modalités</h4>\n      <table >\n        <thead><tr><th>Modalité</th><th>Indications principales</th><th>Limites / pièges</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <strong>Fonction rénale :</strong> <span class=\"kw-bio\">créatininémie, DFG</span> avant injection de PDC<br>\n              <strong>Hémostase :</strong> <span class=\"kw-bio\">NFS, TP, TCA</span> avant biopsies<br>\n              <strong>Bilan complémentaire :</strong> <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">calcémie</span> ; <span class=\"kw-bio\">albuminémie</span>\n            </td>\n            <td><span class=\"kw-alerte\">Marqueurs tumoraux sériques NON recommandés ❌</span> — aucune indication ni en diagnostic ni en suivi</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RXT</span> face + profil</strong></td>\n            <td>\n              Place <em>marginale</em> mais toujours demandée pour éliminer d'autres diagnostics<br>\n              <strong>Signes directs :</strong> <span class=\"kw-imagerie\">opacité hilaire/péri-hilaire</span> (limites externes irrégulières/spiculées, interne noyée dans le médiastin) ; <span class=\"kw-imagerie\">opacité périphérique</span> arrondie non systématisée, dense, parfois excavée par nécrose<br>\n              <strong>Signes indirects :</strong> <span class=\"kw-imagerie\">atélectasie</span> segmentaire/lobaire (obstruction bronchique) ; <span class=\"kw-imagerie\">épanchement pleural</span> ; <span class=\"kw-imagerie\">adénopathies hilaires/médiastinales</span> ; <span class=\"kw-imagerie\">lyse costale ou vertébrale</span> ; <span class=\"kw-imagerie\">ascension d'une coupole diaphragmatique</span> (<span class=\"kw-clinique\">paralysie phrénique</span>)\n            </td>\n            <td>\n              <span class=\"kw-alerte\">RXT normale n'élimine PAS le diagnostic ❌</span> (rare en cancer avéré, &lt;<span class=\"kw-chiffre\"> 5 %</span>)<br>\n              Sensibilité insuffisante pour le dépistage\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoracique injectée</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">Examen pivot du bilan loco-régional</span><br>\n              Précise : <span class=\"kw-imagerie\">topographie</span>, caractère hiliaire central / périphérique, caractère systématisé, rétractile ou non, <span class=\"kw-imagerie\">rapports avec les structures avoisinantes</span><br>\n              Reconstruction <span class=\"kw-imagerie\">MIP (maximum intensity projection)</span> : meilleure énumération des nodules<br>\n              Recherche de FdR associés : <span class=\"kw-imagerie\">plaques pleurales asbestosiques</span> ; <span class=\"kw-imagerie\">adénopathies médiastinales</span>\n            </td>\n            <td>Faux négatifs possibles pour les très petites lésions endobronchiques</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TEP</span> au <span class=\"kw-chiffre\">¹⁸F-FDG</span></strong></td>\n            <td>\n              <strong>Nodule pulmonaire incertain :</strong> <span class=\"kw-def\">RVP</span> de <span class=\"kw-chiffre\">4</span><br>\n              <strong>Bilan d'extension à distance :</strong> si tumeur a priori éligible à un traitement local (chirurgie ou radiothérapie) — bonne <span class=\"kw-def\">VPN</span><br>\n              <strong>Staging médiastinal :</strong> tumeur a priori opérable, vérification d'une <span class=\"kw-imagerie\">adénopathie de taille normale au TDM mais hyperfixante</span>\n            </td>\n            <td>\n              <strong>Faux négatifs :</strong> nodule <span class=\"kw-chiffre\">&lt; 1 cm</span> ; <span class=\"kw-imagerie\">verre dépoli pur</span><br>\n              <strong>Faux positifs :</strong> infections chroniques (actinomycose, nocardiose), mycobactérioses, aspergilloses, sarcoïdose<br>\n              <strong>Fixations physiologiques :</strong> vésicale, colique, cardiaque, cérébrale ✅<br>\n              <span class=\"kw-alerte\">Inutile si métastases visibles d'emblée au TDM ❌</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Scintigraphie DOTATOC</strong> (<span class=\"kw-bio\">récepteurs somatostatine</span>)</td>\n            <td><span class=\"kw-clinique\">Tumeurs carcinoïdes bronchiques</span></td>\n            <td><span class=\"kw-alerte\">Ne dispense PAS de la biopsie ❌</span> (<span class=\"kw-def\">histologie requise</span>) ; exérèse de toute façon nécessaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le cancer bronchopulmonaire primitif apparaît le plus souvent sous forme d'un <strong>nodule pulmonaire isolé</strong>. Toute caractérisation d'un nodule passe par l'imagerie d'orientation + (selon le risque) biopsie histologique.\n      </div>","frequence":3},{"id":"309-8","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie de face d’un adénocarcinome pulmonaire","contenu":"<div class=\"callout callout-warn\">\n        <strong>Image à compléter.</strong> La planche de la banque d'imagerie (<span class=\"kw-imagerie\">RP</span> d'adénocarcinome, p.69) n'est pas encore disponible en fichier local dans <code>assets/images/309/</code>. La sémiologie est rédigée ci-dessous à partir de la fiche source <code>fiches sources/309/</code> ; à enrichir avec la radio (banque CEP ou Radiopaedia) dès extraction.\n      </div>\n      <!-- TODO Kevin : RP adénocarcinome (banque p.69) à intégrer dans assets/images/309/ + légende -->\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémio attendue d'un adénocarcinome pulmonaire en <span class=\"kw-imagerie\">RXT</span></h4>\n      <p>L'<span class=\"kw-def\">adénocarcinome</span> est typiquement <span class=\"kw-imagerie\">périphérique / distal</span>, à la différence du carcinome épidermoïde proximal. Sa traduction radiographique combine quelques signes directs et indirects à reconnaître.</p>\n\n      <table >\n        <thead><tr><th>Type de signe</th><th>Aspect en <span class=\"kw-imagerie\">RXT</span> de face</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Signe direct</strong></td>\n            <td>\n              <strong>Opacité périphérique</strong> arrondie, <span class=\"kw-imagerie\">non systématisée</span>, dense<br>\n              <strong>Contours :</strong> irréguliers, parfois <span class=\"kw-imagerie\">spiculés</span> ; <strong>attire les structures de voisinage</strong><br>\n              <strong>Localisation :</strong> volontiers <span class=\"kw-alerte\">lobaire supérieure ⚠️</span> (drapeau rouge pour la malignité)<br>\n              <strong>Excavation par nécrose centrale :</strong> possible mais moins fréquente que pour l'épidermoïde\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes indirects</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">Adénopathies</span> hilaires ou médiastinales associées<br>\n              Épanchement pleural (extension pleurale)<br>\n              <span class=\"kw-imagerie\">Lyse costale ou vertébrale</span> par contiguïté<br>\n              Ascension de coupole diaphragmatique (paralysie phrénique)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span class=\"kw-imagerie\">RXT</span> a une place <em>marginale</em> dans le diagnostic de cancer du poumon, mais elle reste systématique en face + profil pour éliminer un diagnostic différentiel. Une <span class=\"kw-alerte\">RXT normale n'élimine PAS le diagnostic ❌</span> ; en cas de doute, c'est le <span class=\"kw-imagerie\">TDM thoracique injecté</span> qui prend le relais.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège QCM.</strong> Une opacité périphérique chez un fumeur évoque en premier l'adénocarcinome — mais une opacité <span class=\"kw-imagerie\">proximale / hilaire</span> avec atélectasie segmentaire oriente plutôt vers un <span class=\"kw-def\">épidermoïde</span>.\n      </div>","frequence":2},{"id":"309-9","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie thoracique en fenêtre parenchymateuse d’une tumeur primitive du poumon","contenu":"<div class=\"callout callout-warn\">\n        <strong>Image à compléter.</strong> La planche de la banque d'imagerie (<span class=\"kw-imagerie\">TDM</span> thoracique en fenêtre parenchymateuse, p.70) n'est pas encore disponible en fichier local dans <code>assets/images/309/</code>. La sémiologie est rédigée ci-dessous à partir de la fiche source <code>fiches sources/309/</code> ; à enrichir avec l'image (banque CEP ou Radiopaedia) dès extraction.\n      </div>\n      <!-- TODO Kevin : TDM fenêtre parenchymateuse (banque p.70) à intégrer dans assets/images/309/ + légende -->\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémio attendue en fenêtre parenchymateuse</h4>\n      <p>La <span class=\"kw-imagerie\">TDM thoracique en fenêtre parenchymateuse</span> est l'examen pivot pour caractériser une tumeur primitive du poumon. Elle précise la topographie, les rapports, la densité, et oriente la stratégie biopsique.</p>\n\n      <table >\n        <thead><tr><th>Élément</th><th>Critères de malignité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Taille</strong></td>\n            <td><span class=\"kw-chiffre\">&gt; 1 cm</span> = haut risque ; <span class=\"kw-chiffre\">&lt; 1 cm</span> = surveillance possible</td>\n          </tr>\n          <tr>\n            <td><strong>Contours</strong></td>\n            <td><span class=\"kw-imagerie\">Irréguliers, spiculés</span> ; attire les structures de voisinage</td>\n          </tr>\n          <tr>\n            <td><strong>Localisation</strong></td>\n            <td><span class=\"kw-alerte\">Lobaire supérieure ⚠️</span> = drapeau rouge</td>\n          </tr>\n          <tr>\n            <td><strong>Densité</strong></td>\n            <td>\n              <strong>Solide :</strong> évolution surveillée à <span class=\"kw-chiffre\">2 ans</span><br>\n              <strong>Verre dépoli pur :</strong> évolution surveillée à <span class=\"kw-chiffre\">3-5 ans</span> ; <span class=\"kw-chiffre\">≤ 3 cm</span> → AIS<br>\n              <strong>Mixte (solide + VD) :</strong> composant solide &gt;<span class=\"kw-chiffre\"> 5 mm</span> → adénocarcinome invasif\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Calcifications</strong></td>\n            <td>\n              <strong>Bénignité :</strong> totalement calcifié ; centrale orthogonale ; périphérique ; lamellaire<br>\n              <strong>Exception :</strong> tumeurs carcinoïdes bronchiques peuvent se calcifier\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prise de contraste</strong></td>\n            <td>Présence d'une <span class=\"kw-imagerie\">prise de contraste après injection</span> = argument de malignité</td>\n          </tr>\n          <tr>\n            <td><strong>Rapports anatomiques</strong></td>\n            <td>\n              Paroi thoracique (envahissement pariétal)<br>\n              Médiastin (engainement vasculaire, dysphonie)<br>\n              Plèvre (épanchement, plaques asbestosiques associées)<br>\n              Adénopathies médiastinales (<span class=\"kw-imagerie\">TEP</span> indispensable pour staging)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Reconstructions MIP</strong></td>\n            <td><span class=\"kw-imagerie\">Sommation des coupes</span> sus et sous-jacentes pour mieux énumérer les nodules</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le <span class=\"kw-imagerie\">TDM</span> thoracique injecté précise la <strong>topographie</strong>, identifie un <span class=\"kw-imagerie\">cancer périphérique vs proximal</span>, et oriente le choix de la technique biopsique (<span class=\"kw-imagerie\">fibroscopie</span> pour les centraux ; ponction transpariétale pour les périphériques).\n      </div>","frequence":1},{"id":"309-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principales investigations à visée diagnostique d’un cancer bronchique","contenu":"<p>Le diagnostic d'un cancer bronchique repose sur une <span class=\"kw-def\">preuve histologique</span> ✅. La <span class=\"kw-alerte\">cytologie n'est PAS un standard</span> ❌. Cinq grands abords biopsiques selon la localisation et l'extension.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Techniques biopsiques</h4>\n      <table >\n        <thead><tr><th>Technique</th><th>Anesthésie</th><th>Cibles</th><th>CI / Complications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fibroscopie bronchique</strong> (<span class=\"kw-imagerie\">bronchoscopie</span> souple) ⭐</td>\n            <td><span class=\"kw-clinique\">Locale</span> ou générale (sédation)</td>\n            <td>\n              <strong>Systématique en cas de suspicion de cancer bronchique</strong><br>\n              Bronches centrales jusqu'au niveau <span class=\"kw-chiffre\">sous-segmentaire</span><br>\n              Biopsies : <span class=\"kw-chiffre\">3 à 5</span> ; systématiques de l'éperon sus-jacent et de la carène\n            </td>\n            <td>\n              <strong>CI absolues :</strong><br>\n              <span class=\"kw-ci\">Hypoxémie réfractaire</span> à l'oxygénothérapie<br>\n              <span class=\"kw-ci\">Anomalies majeures de coagulation</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>EBUS / EUS</strong> (écho-endoscopie bronchique ou œsophagienne)</td>\n            <td><span class=\"kw-clinique\">Générale</span></td>\n            <td>\n              Tumeur centrale <strong>sous-muqueuse</strong> ou <strong>péri-bronchique</strong><br>\n              <strong>Adénopathies médiastinales</strong> (1ʳᵉ intention pour staging anatomopathologique N)\n            </td>\n            <td>Idem <span class=\"kw-imagerie\">fibroscopie bronchique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Ponction transpariétale à l'aiguille</strong></td>\n            <td><span class=\"kw-clinique\">Locale</span> ; guidage <span class=\"kw-imagerie\">TDM</span> (± écho-guidée si contact pariétal)</td>\n            <td>\n              <strong>Nodules et masses périphériques</strong><br>\n              Sensibilité <span class=\"kw-chiffre\">90 %</span><br>\n              Négativité (<span class=\"kw-chiffre\">10-15 %</span>) n'élimine pas le diagnostic\n            </td>\n            <td>\n              <strong>Hémoptysie :</strong> rare<br>\n              <strong>Pneumothorax :</strong> <span class=\"kw-chiffre\">10 %</span> des cas — souvent minime mais peut être mal toléré si insuffisance respiratoire (d'où l'<span class=\"kw-clinique\">évaluation spirométrique préalable</span>)<br>\n              <span class=\"kw-alerte\">Piège QCM : épanchement pleural NON listé en complication ❌</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Techniques chirurgicales</strong></td>\n            <td>Générale</td>\n            <td>\n              Si suspicion forte de cancer et échec des gestes moins invasifs<br>\n              <strong>Médiastinoscopie :</strong> sites ganglionnaires latéro-trachéaux<br>\n              <strong>Thoracoscopie / vidéo-thoracoscopie :</strong> épanchement exsudatif ; aires ganglionnaires non accessibles en médiastinoscopie (gauche, sous-carinaire)<br>\n              <strong>Vidéo-thoracotomie exploratrice :</strong> en cas d'échec ou de CI aux autres techniques\n            </td>\n            <td>Risques chirurgicaux standards</td>\n          </tr>\n          <tr>\n            <td><strong>Lésion à distance</strong></td>\n            <td>Selon site</td>\n            <td>\n              <strong>Adénopathie sus-claviculaire</strong> ou <strong>métastase cutanée</strong> : à prioriser (affirme respectivement N3 et M1, peu de complications)<br>\n              <strong>Métastase hépatique</strong> ; lésion ostéolytique ; <span class=\"kw-imagerie\">métastase cérébrale prévalente</span><br>\n              <strong>Biopsie pleurale</strong> si épanchement suffisamment abondant\n            </td>\n            <td>Adaptées au site</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Bilan moléculaire (à la phase diagnostique)</h4>\n      <p>L'émergence des <span class=\"kw-ttt\">thérapies ciblées</span> (ITK) et de l'<span class=\"kw-ttt\">immunothérapie</span> a modifié la stratégie diagnostique : il faut <strong>matériel histologique en quantité suffisante</strong> pour réaliser toutes les analyses.</p>\n\n      <table >\n        <thead><tr><th></th><th>Indication</th><th>Recherche</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Thérapie ciblée</strong></td>\n            <td>\n              Tous CNPC <strong>non épidermoïdes</strong> métastatiques (majorité d'adénocarcinomes)<br>\n              Cancer épidermoïde du non-fumeur (cas rare) ‼️\n            </td>\n            <td>\n              <strong>Bilan minimal CEP :</strong> <span class=\"kw-bio\">EGFR</span> ; <span class=\"kw-bio\">ALK</span> ; <span class=\"kw-bio\">ROS1</span> ; <span class=\"kw-bio\">KRAS</span><br>\n              <strong>Ajout en oncologie :</strong> <span class=\"kw-bio\">B-RAF</span> ; <span class=\"kw-bio\">HER-2</span><br>\n              <strong>Régulièrement ajoutés :</strong> PIK3CA ; MET\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Immunothérapie</strong></td>\n            <td>Tous CNPC de stade avancé ou métastatique (adéno ou épidermoïde)</td>\n            <td>Expression de <span class=\"kw-bio\">PD-L1</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir — répartition driver dans les adénocarcinomes métastatiques.</strong> <span class=\"kw-bio\">EGFR</span> muté dans <span class=\"kw-chiffre\">12 %</span> (<span class=\"kw-chiffre\">44 %</span> chez les non-fumeurs), <span class=\"kw-bio\">ALK</span> transloqué dans <span class=\"kw-chiffre\">5 %</span> (<span class=\"kw-chiffre\">14 %</span> chez les non-fumeurs), <span class=\"kw-bio\">KRAS</span> muté dans <span class=\"kw-chiffre\">30 %</span> — mutations <strong>mutuellement exclusives</strong>.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> <span class=\"kw-bio\">EGFR</span> a un sens opposé selon le cancer : <em>mutation présente</em> pour traiter un CP par anti-EGFR ; <em>mutation absente</em> pour traiter un cancer colique par anti-EGFR.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 293 — Anapath · 206 — Epanchement pleural</em></p>","frequence":5},{"id":"309-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","contenu":"<p>La prise en charge se décline en 3 questions séquentielles : <strong>(1)</strong> à petites cellules ou non à petites cellules ? <strong>(2)</strong> si CNPC, résécable ou non ? <strong>(3)</strong> si résécable, opérable ?</p>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute tumeur <span class=\"kw-imagerie\">localisée au thorax</span> peut bénéficier d'un traitement à visée curative (chirurgie ou radio-chimiothérapie).\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">CNPC — stratégie par stade</h4>\n      <table >\n        <thead><tr><th>Stade</th><th>Fréquence</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cancer localisé</strong><br><em>Stade I-II</em></td>\n            <td><span class=\"kw-chiffre\">15-30 %</span></td>\n            <td>\n              <strong>Opérable :</strong> <span class=\"kw-ttt\">chirurgie d'exérèse</span> + <span class=\"kw-clinique\">curage ganglionnaire hiliaire et médiastinal homolatéral</span> ± <span class=\"kw-ttt\">chimiothérapie adjuvante</span> selon le stade post-opératoire<br>\n              <strong>Inopérable :</strong> <span class=\"kw-ttt\">radiothérapie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cancer localement avancé</strong><br><em>Stade III</em></td>\n            <td><span class=\"kw-chiffre\">20 %</span></td>\n            <td>\n              <span class=\"kw-ttt\">Radiothérapie + chimiothérapie</span> concomitantes<br>\n              <strong>Maintenance :</strong> <span class=\"kw-ttt\">immunothérapie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cancer disséminé</strong><br><em>Stade IV</em></td>\n            <td><span class=\"kw-chiffre\">40-55 %</span></td>\n            <td>\n              Traitement systémique exclusif, options selon le profil moléculaire :<br>\n              <strong>Altération moléculaire ciblable :</strong> <span class=\"kw-ttt\">ITK</span><br>\n              <strong>PD-L1 &gt;<span class=\"kw-chiffre\"> 50 %</span> :</strong> <span class=\"kw-ttt\">immunothérapie seule</span> (<span class=\"kw-ttt\">pembrolizumab</span>)<br>\n              <strong>Chimiothérapie conventionnelle :</strong> <span class=\"kw-ttt\">doublet à base de sel de platine</span><br>\n              <strong>Combinaison :</strong> <span class=\"kw-ttt\">chimiothérapie + immunothérapie</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">CBPC — stratégie thérapeutique</h4>\n      <div class=\"callout callout-danger\">\n        <strong>Urgence oncologique 🔥.</strong> Évolution rapide sans traitement : décès en <span class=\"kw-chiffre\">&lt; 3 mois</span>. Chimiothérapie à instaurer le <strong>plus précocement possible</strong>.\n      </div>\n\n      <table >\n        <thead><tr><th>Forme</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Formes limitées</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Radio-chimiothérapie concomitante</span> : doublet à base de sel de platine + radiothérapie thoracique précoce (tumeur + médiastin)<br>\n              Si réponse complète et <span class=\"kw-clinique\">patient &lt; 70 ans</span> : <span class=\"kw-ttt\">irradiation prophylactique cérébrale</span> conseillée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Formes diffuses</strong></td>\n            <td><span class=\"kw-ttt\">Doublet à base de sel de platine + immunothérapie</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège chirurgical.</strong> Le CBPC n'est qu'<span class=\"kw-alerte\">exceptionnellement opérable</span> et <strong>jamais en traitement isolé</strong>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Bilan préthérapeutique opérabilité (CNPC résécable)</h4>\n      <table >\n        <thead><tr><th>Axe</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>État général</strong></td>\n            <td><span class=\"kw-clinique\">Performans Status</span> (PS) ; <span class=\"kw-clinique\">état nutritionnel</span></td>\n          </tr>\n          <tr>\n            <td><strong>Sujet âgé &gt;<span class=\"kw-chiffre\"> 70-75 ans</span></strong></td>\n            <td><span class=\"kw-clinique\">Évaluation gériatrique</span> (<span class=\"kw-bio\">score G8</span> minimum)</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan fonctionnel respiratoire</strong></td>\n            <td>\n              <span class=\"kw-bio\">Gazométrie artérielle</span> + <span class=\"kw-bio\">EFR</span> (spirométrie + <span class=\"kw-bio\">DLCO</span> ± <span class=\"kw-bio\">VO₂max</span>)<br>\n              Si anomalies : <span class=\"kw-clinique\">épreuve d'effort</span> + <span class=\"kw-imagerie\">scintigraphie pulmonaire de ventilation/perfusion</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>CI à la chirurgie d'exérèse</strong></td>\n            <td>\n              <span class=\"kw-ci\">VEMS prédit post-opératoire &lt; 1 L</span> ou <span class=\"kw-ci\">&lt; 30 % de la théorique</span><br>\n              Une lobectomie réduit le VEMS de <span class=\"kw-chiffre\">25 %</span> (sauf lobe moyen)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bilan cardio-respiratoire</strong></td>\n            <td>\n              <span class=\"kw-bio\">ECG</span> + <span class=\"kw-imagerie\">ETT</span> (FEVG, PAP)<br>\n              ± épreuve d'effort, <span class=\"kw-imagerie\">scintigraphie myocardique</span>, <span class=\"kw-imagerie\">coronarographie</span>, <span class=\"kw-imagerie\">échographie TSAO</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Mesures associées (tous stades)</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Arrêt du tabac</strong> 🛑</td>\n            <td>\n              <span class=\"kw-alerte\">Impératif chez les patients traités à visée curative</span><br>\n              <strong>Chirurgie :</strong> sevrage diminue la fréquence des complications péri-opératoires<br>\n              <strong>Traitement systémique (ITK, chimio) :</strong> tabac diminue l'activité thérapeutique (induction enzymatique hépatique)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Soins supports</strong></td>\n            <td>\n              Seul traitement si <span class=\"kw-clinique\">PS ≥ 3</span> (état général médiocre)<br>\n              Dès l'apparition de symptômes, quel que soit le stade<br>\n              Prise en charge de la dyspnée et de la douleur ; soutien psycho-oncologique ; nutrition\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Douleur</strong></td>\n            <td>\n              Antalgiques par paliers croissants, sans hésiter à recourir à la <span class=\"kw-ttt\">morphine</span><br>\n              Radiothérapie focale antalgique : lésions osseuses, surrénaliennes, cutanées, ou menaçant la moelle<br>\n              Chirurgie parfois avant radiothérapie : enclouage d'os long, laminectomie décompressive<br>\n              Métastases osseuses : antalgiques + <span class=\"kw-ttt\">AINS</span> + <span class=\"kw-ttt\">anti-résorption</span> (bisphosphonate ou anti-RANKL) ± vertébroplastie percutanée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Dyspnée</strong></td>\n            <td>\n              <strong>Lymphangite carcinomateuse :</strong> traitement difficile<br>\n              <strong>Obstruction trachéale/bronchique :</strong> désobstruction ± prothèse endobronchique<br>\n              <strong>Pleurésie néoplasique récidivante :</strong> symphyse pleurale par talcage ou drainage à demeure<br>\n              <strong>Syndrome cave supérieur :</strong> position demi-assise ; oxygénothérapie ; anticoagulant ; <span class=\"kw-ttt\">corticoïdes</span> ± stent cave\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Surveillance</strong></td>\n            <td>\n              Pas de consensus sur les modalités<br>\n              Majorité des rechutes dans les <span class=\"kw-chiffre\">2 années</span> post-diagnostic chez les patients traités à visée curative<br>\n              <span class=\"kw-alerte\">Marqueurs tumoraux sanguins sans utilité ❌</span> — ne pas les doser<br>\n              Risque de 2ⁿᵈ cancer : <span class=\"kw-ci\">ne jamais</span> arrêter la surveillance\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Exposition professionnelle</strong></td>\n            <td>\n              Si tableaux de maladie professionnelle remplis : <span class=\"kw-clinique\">déclaration en maladie professionnelle</span><br>\n              <strong>Amiante :</strong> droit à indemnisation complémentaire par le <span class=\"kw-def\">FIVA</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Plan cancer</strong></td>\n            <td>\n              Principales décisions thérapeutiques validées en <span class=\"kw-def\">RCP</span> d'oncologie thoracique<br>\n              <span class=\"kw-clinique\">Plan personnalisé de soins</span> expliqué dans le dispositif d'annonce<br>\n              Inclusion dans des essais cliniques systématiquement encouragée ✅\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Tumeurs secondaires (métastases pulmonaires)</h4>\n      <p>Tumeurs primitives les plus souvent en cause — moyen mnémotechnique <strong>« PTRSMC »</strong> : <span class=\"kw-etio\">Poumon, Thyroïde, Rein, Sein, Mélanome, Colon-rectum</span>.</p>\n\n      <table >\n        <thead><tr><th>Situation</th><th>Démarche</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cancer primitif inconnu</strong></td>\n            <td>\n              Enquête étiologique : examen clinique + explorations à la recherche d'un cancer accessible (poumon, gonades, thyroïde, sein, endomètre, prostate…)<br>\n              Évoquer en 1ʳᵉ hypothèse une métastase de cancer pulmonaire chez un fumeur ou ex-fumeur<br>\n              <strong><span class=\"kw-imagerie\">TEP</span> au ¹⁸F-FDG</strong> recommandée<br>\n              Si histologie pulmonaire obtenue avant le primitif : orientée par IHC<br>\n              <span class=\"kw-clinique\">RCP indispensable</span>, surtout si recherche négative\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cancer primitif connu</strong></td>\n            <td>\n              Images caractéristiques (<span class=\"kw-imagerie\">lâcher de ballons</span>, lymphangite carcinomateuse typique) → diagnostic probable de métastases<br>\n              Preuve histologique non systématique, exigée par RCP si modification thérapeutique attendue ou phénotype/génotype suspecté\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cancer ancien considéré comme guéri</strong></td>\n            <td>\n              Métastases possibles &gt; <span class=\"kw-chiffre\">10 ans</span> après le traitement initial (sein notamment)<br>\n              Si atteinte pulmonaire isolée : enquête diagnostique complète (prélèvement histologique)<br>\n              Possibilité de traitement radical : chirurgie ou traitement local (<span class=\"kw-ttt\">radiothérapie stéréotaxique</span>, <span class=\"kw-ttt\">radiofréquence</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Présentations radiologiques des métastases</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Nodule(s) parenchymateux</span> métastatique(s) : unique ou multiples (« lâcher de ballons »).</li>\n        <li><span class=\"kw-imagerie\">Lymphangite carcinomateuse</span> : atteinte interstitielle.</li>\n        <li><span class=\"kw-imagerie\">Épanchement pleural exsudatif</span>.</li>\n        <li><span class=\"kw-imagerie\">Adénopathies médiastinales</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction Tabac · 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux · 184 — Accident - maladie professionnel</em></p>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/pulmonary-metastases","label":"Radiopaedia : Pulmonary metastases"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> le <span class=\"kw-etio\">cancer à petites cellules (CPC)</span> est une <span class=\"kw-alerte\">urgence oncologique</span><br><strong>Fenêtre :</strong> <span class=\"kw-ttt\">chimiothérapie</span> le plus précocement possible ; sans traitement, décès en &lt; <span class=\"kw-chiffre\">3 mois</span> (temps de doublement cellulaire court)<br><strong>1er geste :</strong> obtenir la preuve <span class=\"kw-bio\">histologique</span> puis débuter la chimiothérapie</p>","redflags":"<ul><li>AEG inexpliquée : asthénie, anorexie, amaigrissement</li><li><span class=\"kw-clinique\">Douleur thoracique</span> par envahissement pariétal</li><li><span class=\"kw-etio\">Épanchement pleural néoplasique</span> (séro-fibrineux ou séro-hémorragique)</li><li><span class=\"kw-etio\">Syndrome de Pancoast-Tobias</span> (tumeur de l'apex pulmonaire)</li><li><span class=\"kw-etio\">Syndrome cave supérieur</span> (syndrome médiastinal)</li><li><span class=\"kw-clinique\">Dysphonie</span> par compression du nerf récurrent gauche</li><li><span class=\"kw-clinique\">Dysphagie</span> par compression œsophagienne</li><li>Paralysie phrénique (élévation d'une coupole diaphragmatique en <span class=\"kw-imagerie\">RXT</span>)</li><li>Péricardite avec tamponnade ou arythmie récente</li><li>Adénopathies sus-claviculaires, cervicales ou axillaires</li><li>Métastases : SNC, os, foie, surrénales</li><li><span class=\"kw-etio\">MTEV</span> non provoquée (souvent extensive, résistant aux anticoagulants)</li><li>Ces signes d'extension loco-régionale éliminent d'emblée le recours chirurgical (sauf parfois l'envahissement pariétal)</li></ul>","principes":"<p>Toute tumeur localisée au thorax peut bénéficier d'un traitement à visée curative ; toute décision validée en RCP d'oncologie thoracique.</p><p><strong>Préalable & bilan</strong></p><p>Classement TNM en stade <span class=\"kw-def\">localisé (I-II)</span> / <span class=\"kw-def\">localement avancé (III)</span> / <span class=\"kw-def\">disséminé (IV)</span></p><ul><li>Diagnostic positif = <span class=\"kw-bio\">histologie</span> obligatoire (la cytologie n'est pas un standard)</li><li><span class=\"kw-imagerie\">Fibroscopie bronchique</span> systématique, sauf hypoxémie réfractaire ou anomalie majeure de la coagulation</li><li>Lésion centrale → <span class=\"kw-imagerie\">fibroscopie bronchique</span> ; lésion périphérique → <span class=\"kw-imagerie\">ponction transpariétale</span> guidée <span class=\"kw-imagerie\">TDM</span></li><li>Bilan moléculaire (CNPC avancé) : <span class=\"kw-bio\">EGFR</span>, <span class=\"kw-bio\">KRAS</span>, <span class=\"kw-bio\">ALK</span>, <span class=\"kw-bio\">ROS1</span> + expression <span class=\"kw-bio\">PD-L1</span></li></ul><p><strong>CNPC localisé (stade I-II)</strong></p><p>Opérabilité = <span class=\"kw-bio\">VEMS</span> prédit post-op ≥ <span class=\"kw-chiffre\">1 L</span> et ≥ <span class=\"kw-chiffre\">30 %</span> de la théorique</p><ul><li>Opérable → <span class=\"kw-ttt\">chirurgie d'exérèse</span> + <span class=\"kw-ttt\">curage ganglionnaire hiliaire et médiastinal homolatéral</span></li><li>± <span class=\"kw-ttt\">chimiothérapie</span> selon le stade post-opératoire</li><li>Inopérable → <span class=\"kw-ttt\">radiothérapie</span></li></ul><p><strong>CNPC localement avancé (stade III)</strong></p><ul><li><span class=\"kw-ttt\">Radiothérapie + chimiothérapie</span></li><li>Traitement de maintenance : <span class=\"kw-ttt\">immunothérapie</span></li></ul><p><strong>CNPC disséminé (stade IV)</strong></p><ul><li>Altération moléculaire ciblable → <span class=\"kw-ttt\">ITK</span> (thérapie ciblée)</li><li><span class=\"kw-bio\">PD-L1</span> &gt; <span class=\"kw-chiffre\">50 %</span> → <span class=\"kw-ttt\">immunothérapie</span> seule (<span class=\"kw-ttt\">pembrolizumab</span>)</li><li>Sinon → <span class=\"kw-ttt\">chimiothérapie</span> doublet à base de <span class=\"kw-ttt\">sel de platine</span> ± immunothérapie</li></ul><p><strong>Cancer à petites cellules (CPC)</strong></p><ul><li><span class=\"kw-alerte\">Urgence oncologique</span> : chimiothérapie le plus précocement possible (décès &lt; <span class=\"kw-chiffre\">3 mois</span> sans traitement)</li><li>Exceptionnellement opérable, jamais la chirurgie seule</li><li>Forme limitée → <span class=\"kw-ttt\">radio-chimiothérapie concomitante</span> (doublet platine + RT thoracique précoce)</li><li>Réponse complète & &lt; <span class=\"kw-chiffre\">70 ans</span> → <span class=\"kw-ttt\">irradiation prophylactique cérébrale</span></li><li>Forme diffuse → doublet <span class=\"kw-ttt\">platine</span> + <span class=\"kw-ttt\">immunothérapie</span></li></ul><p><strong>Mesures associées & soins supports</strong></p><ul><li><span class=\"kw-ttt\">Arrêt du tabac</span> impératif (réduit les complications péri-op ; le tabac réduit l'efficacité des ITK/chimio)</li><li>Soins supports : <span class=\"kw-ttt\">antalgiques</span> par paliers (<span class=\"kw-ttt\">morphine</span>), dyspnée, soutien psycho-oncologique, nutrition</li><li><span class=\"kw-etio\">Syndrome cave supérieur</span> : demi-assis, O2, anticoagulant, <span class=\"kw-ttt\">corticoïdes</span> ± stent cave</li><li>Pleurésie néoplasique récidivante → symphyse pleurale (talcage) ou drainage à demeure</li><li>Cancer lié à l'<span class=\"kw-etio\">amiante</span> → déclaration en maladie professionnelle + indemnisation <span class=\"kw-ttt\">FIVA</span></li></ul>","suivi":"<p><strong>Rechutes :</strong> majorité dans les <span class=\"kw-chiffre\">2 ans</span> suivant le diagnostic (patients traités à visée curative)<br><strong>Marqueurs tumoraux sanguins :</strong> aucune utilité, <span class=\"kw-bio\">ne pas prélever</span><br><strong>Durée :</strong> <span class=\"kw-ci\">ne jamais</span> arrêter la surveillance (risque de <span class=\"kw-etio\">2nd cancer</span>)<br><strong>Alerte :</strong> réapparition de signes <span class=\"kw-etio\">paranéoplasiques</span> après résection = <span class=\"kw-alerte\">rechute tumorale</span></p>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_309_CANCER_2023.pdf","label":"Collège (CEP) — Item 309 cancer 2023"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Cancer du poumon prouvé (histologie) — Bilan d'extension TNM réalisé","detail":"<h4>CAT — stratégie thérapeutique du cancer du poumon — Après preuve histologique et bilan d'extension TNM, en RCP d'oncologie thoracique</h4>","branches":[{"to":"q1","label":"Type histologique","color":"blue"}]},{"id":"q1","kind":"decision","label":"Cancer à petites cellules (CPC) ? — Question 1 : type histologique","branches":[{"to":"q-cpc","label":"Oui — CPC (≈ 15 %)","color":"red"},{"to":"q2","label":"Non — CNPC (> 80 %)","color":"blue"}]},{"id":"q-cpc","kind":"decision","label":"Forme limitée au thorax ?","branches":[{"to":"t-cpc-lim","label":"Forme limitée","color":"amber"},{"to":"t-cpc-diff","label":"Forme diffuse / métastatique","color":"red"}]},{"id":"t-cpc-lim","kind":"terminal","label":"Radio-chimiothérapie concomitante","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Radio-chimiothérapie concomitante</span> : doublet à base de <span class=\"kw-ttt\">sel de platine</span> + radiothérapie thoracique précoce (tumeur + médiastin)</li><li><span class=\"kw-alerte\">Urgence oncologique</span> : chimiothérapie instaurée le plus précocement possible</li></ul><h4>Si réponse complète</h4><ul><li><span class=\"kw-ttt\">Irradiation prophylactique cérébrale</span> conseillée si patient &lt; <span class=\"kw-chiffre\">70 ans</span></li></ul>"},{"id":"t-cpc-diff","kind":"terminal","label":"Chimiothérapie + immunothérapie","color":"red","detail":"<h4>Conduite</h4><ul><li>Traitement systémique exclusif : doublet à base de <span class=\"kw-ttt\">sel de platine</span> + <span class=\"kw-ttt\">immunothérapie</span></li><li><span class=\"kw-alerte\">Urgence oncologique</span> : grande chimiosensibilité initiale mais rechute précoce (notamment cérébrale)</li></ul>"},{"id":"q2","kind":"decision","label":"Tumeur résécable (stade localisé I-II) ? — Question 2 : CNPC","branches":[{"to":"q3","label":"Oui — résécable","color":"green"},{"to":"q-stade","label":"Non — non résécable","color":"amber"}]},{"id":"q3","kind":"decision","label":"Patient opérable ? — Question 3 : bilan fonctionnel respiratoire","branches":[{"to":"t-op","label":"Oui — opérable","color":"green"},{"to":"t-inop","label":"Non — inopérable","color":"amber"}]},{"id":"t-op","kind":"terminal","label":"Chirurgie d'exérèse + curage","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Chirurgie d'exérèse</span> + <span class=\"kw-ttt\">curage ganglionnaire hiliaire et médiastinal homolatéral</span></li><li>± <span class=\"kw-ttt\">chimiothérapie</span> selon le stade post-opératoire</li></ul><h4>Opérabilité</h4><ul><li><span class=\"kw-bio\">VEMS</span> prédit post-opératoire ≥ <span class=\"kw-chiffre\">1 L</span> et ≥ <span class=\"kw-chiffre\">30 %</span> de la théorique</li><li><span class=\"kw-ttt\">Arrêt du tabac</span> impératif (réduit les complications péri-opératoires)</li></ul>"},{"id":"t-inop","kind":"terminal","label":"Radiothérapie","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Radiothérapie</span> à visée curative (tumeur localisée non opérable)</li></ul>"},{"id":"q-stade","kind":"decision","label":"Stade III ou stade IV ?","branches":[{"to":"t-iii","label":"Stade III (localement avancé)","color":"amber"},{"to":"t-iv","label":"Stade IV (disséminé)","color":"red"}]},{"id":"t-iii","kind":"terminal","label":"Radio-chimiothérapie + immunothérapie de maintenance","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Radiothérapie + chimiothérapie</span></li><li>Traitement de maintenance : <span class=\"kw-ttt\">immunothérapie</span></li></ul>"},{"id":"t-iv","kind":"terminal","label":"Traitement systémique exclusif","color":"red","detail":"<h4>Conduite</h4><ul><li>Altération moléculaire ciblable → <span class=\"kw-ttt\">ITK</span> (thérapie ciblée)</li><li><span class=\"kw-bio\">PD-L1</span> &gt; <span class=\"kw-chiffre\">50 %</span> → <span class=\"kw-ttt\">immunothérapie</span> seule (<span class=\"kw-ttt\">pembrolizumab</span>)</li><li>Sinon → <span class=\"kw-ttt\">chimiothérapie</span> doublet à base de <span class=\"kw-ttt\">sel de platine</span> ± immunothérapie</li></ul><h4>Préalable</h4><ul><li>Bilan moléculaire : <span class=\"kw-bio\">EGFR</span>, <span class=\"kw-bio\">KRAS</span>, <span class=\"kw-bio\">ALK</span>, <span class=\"kw-bio\">ROS1</span> + expression <span class=\"kw-bio\">PD-L1</span></li></ul>"}]},"cards":[{"i":"486d5e8516db","n":309,"o":"309-10","u":"Examens complémentaires","t":"Connaître les principales investigations à visée diagnostique d’un cancer bronchique","q":"Quel est l'objectif du bilan moléculaire dans le diagnostic du cancer bronchique et quels sont les gènes à rechercher pour les thérapies ciblées ?","a":"<p>Le bilan moléculaire vise à obtenir suffisamment de matériel histologique pour les analyses nécessaires aux <strong>thérapies ciblées</strong> et à l'<strong>immunothérapie</strong>, suite à l'évolution des stratégies diagnostiques.</p><p>Pour les thérapies ciblées, chez les cancers du poumon non à petites cellules (CNPC) non épidermoïdes métastatiques (majoritairement adénocarcinomes) et le cas rare de cancer épidermoïde chez le non-fumeur, les gènes à rechercher minimalement sont : <strong>EGFR, ALK, ROS1, KRAS</strong>. Des ajouts en oncologie incluent <strong>B-RAF et HER-2</strong>, et plus régulièrement <strong>PIK3CA et MET</strong>.</p>"},{"i":"48acbc37e542","n":309,"o":"309-10","u":"Examens complémentaires","t":"Connaître les principales investigations à visée diagnostique d’un cancer bronchique","q":"Quelles sont les contre-indications absolues et les principales complications de la fibroscopie bronchique pour le diagnostic de cancer du poumon ?","a":"<ul><li>Les contre-indications absolues sont l'<strong>hypoxémie réfractaire à l'oxygénothérapie</strong> et les <strong>anomalies majeures de la coagulation</strong>.</li><li>Les complications ne sont pas spécifiées dans le contenu source pour la fibroscopie bronchique seule.</li></ul>"},{"i":"4900b4817860","n":309,"o":"309-10","u":"Examens complémentaires","t":"Connaître les principales investigations à visée diagnostique d’un cancer bronchique","q":"Quelles sont les principales complications de la ponction transpariétale à l'aiguille guidée par TDM pour le diagnostic d'un nodule ou d'une masse périphérique pulmonaire ?","a":"<ul><li>Une <strong>hémoptysie</strong> (rare).</li><li>Un <strong>pneumothorax</strong> dans <strong>10%</strong> des cas, souvent minime mais pouvant être mal toléré en cas d'insuffisance respiratoire (nécessitant une évaluation spirométrique préalable).</li></ul><p>L'épanchement pleural n'est pas une complication listée pour cette technique.</p>"},{"i":"7be259fdb87c","n":309,"o":"309-10","u":"Examens complémentaires","t":"Connaître les principales investigations à visée diagnostique d’un cancer bronchique","q":"Sur quoi repose le diagnostic de certitude d'un cancer bronchique et quelle est la place de la cytologie ?","a":"<p>Le diagnostic de certitude d'un cancer bronchique repose impérativement sur une <strong>preuve histologique</strong>. La cytologie n'est <strong>pas un standard</strong> pour le diagnostic.</p>"},{"i":"c42fdedf1576","n":309,"o":"309-10","u":"Examens complémentaires","t":"Connaître les principales investigations à visée diagnostique d’un cancer bronchique","q":"Dans quels types de cancers bronchiques et à quel stade est effectuée la recherche d'expression de PD-L1 pour l'immunothérapie ?","a":"<p>La recherche d'expression de <strong>PD-L1</strong> est effectuée pour l'immunothérapie dans <strong>tous les cancers du poumon non à petites cellules (CNPC) de stade avancé ou métastatique</strong>, qu'ils soient de type adénocarcinome ou épidermoïde.</p>"},{"i":"f70da86156eb","n":309,"o":"309-10","u":"Examens complémentaires","t":"Connaître les principales investigations à visée diagnostique d’un cancer bronchique","q":"Quels sont les cinq grands abords biopsiques utilisés pour le diagnostic d'un cancer bronchique selon la localisation et l'extension ?","a":"<ul><li>La <strong>fibroscopie bronchique</strong> (bronchoscopie souple) pour les bronches centrales jusqu'au niveau sous-segmentaire.</li><li>L'<strong>EBUS/EUS</strong> (écho-endoscopie bronchique ou œsophagienne) pour les tumeurs centrales sous-muqueuses/péri-bronchiques et les adénopathies médiastinales.</li><li>La <strong>ponction transpariétale à l'aiguille</strong> (guidage TDM ou échographique) pour les nodules et masses périphériques.</li><li>Les <strong>techniques chirurgicales</strong> (médiastinoscopie, thoracoscopie/vidéo-thoracoscopie, vidéo-thoracotomie exploratrice) si forte suspicion et échec des gestes moins invasifs.</li><li>La <strong>biopsie de lésion à distance</strong> (adénopathie sus-claviculaire, métastase cutanée, hépatique, cérébrale, ou pleurale) selon le site.</li></ul>"},{"i":"053fe6e12a10","n":309,"o":"309-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","q":"Quelles sont les mesures associées à la prise en charge d'un cancer du poumon, quel que soit le stade ?","a":"<ul><li><strong>Arrêt du tabac</strong> : Impératif, il diminue les complications péri-opératoires et augmente l'efficacité des traitements systémiques.</li><li><strong>Soins de support</strong> : Dès l'apparition des symptômes, quel que soit le stade, et seul traitement si PS ≥ 3 (état général médiocre). Incluent la gestion de la dyspnée, de la douleur, le soutien psycho-oncologique et la nutrition.</li><li><strong>Prise en charge de la douleur</strong> : Antalgiques paliers croissants (incluant morphine), radiothérapie focale antalgique pour certaines lésions, et parfois chirurgie (enclouage d'os long, laminectomie). Pour les métastases osseuses, antalgiques + AINS + <strong>anti-résorption</strong> (bisphosphonates ou anti-RANKL).</li><li><strong>Prise en charge de la dyspnée</strong> : Selon la cause : désobstruction ± prothèse endobronchique, symphyse pleurale ou drainage pour pleurésie, gestion du syndrome cave supérieur (position, oxygène, anticoagulants, corticoïdes, stent).</li></ul>"},{"i":"175bfd10e5b6","n":309,"o":"309-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","q":"Comment est prise en charge une tumeur pulmonaire à petites cellules (CBPC) ?","a":"<p>Le CBPC est une <strong>urgence oncologique</strong> en raison de son évolution rapide. La <strong>chimiothérapie</strong> doit être instaurée le plus précocement possible :</p><ul><li><strong>Formes limitées</strong> : Radio-chimiothérapie concomitante (doublet à base de sel de platine + radiothérapie thoracique précoce). Si réponse complète et patient < 70 ans, <strong>irradiation prophylactique cérébrale</strong> est conseillée.</li><li><strong>Formes diffuses</strong> : Doublet à base de sel de platine + immunothérapie.</li></ul><p>Le CBPC n'est qu'<strong>exceptionnellement opérable</strong> et jamais en traitement isolé.</p>"},{"i":"277d53b23872","n":309,"o":"309-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","q":"Quels sont les éléments du bilan préthérapeutique pour évaluer l'opérabilité d'un Carcinome Non à Petites Cellules (CNPC) résécable ?","a":"<p>Les éléments clés du bilan préthérapeutique sont :</p><ul><li><strong>État général</strong> : Évaluation du Performans Status (PS) et de l'état nutritionnel. Pour les sujets âgés (> 70-75 ans), une évaluation gériatrique avec le <strong>score G8</strong> minimum.</li><li><strong>Bilan fonctionnel respiratoire</strong> : Gazométrie artérielle, <strong>EFR</strong> (spirométrie + DLCO ± VO₂max). Si anomalies, épreuve d'effort et scintigraphie pulmonaire de ventilation/perfusion. Une <strong>CI à la chirurgie</strong> est un VEMS prédit post-opératoire <strong>< 1 L ou < 30 %</strong> de la théorique.</li><li><strong>Bilan cardio-respiratoire</strong> : ECG, ETT (FEVG, PAP), potentiellement épreuve d'effort, scintigraphie myocardique, coronarographie, échographie TSAO.</li></ul>"},{"i":"55639bd95cd2","n":309,"o":"309-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","q":"Quelles sont les tumeurs primitives les plus fréquentes à l'origine de métastases pulmonaires ?","a":"<p>Les tumeurs primitives les plus souvent en cause sont celles récapitulées par le moyen mnémotechnique « PTRSMC » :</p><ul><li><strong>P</strong>oumon</li><li><strong>T</strong>hyroïde</li><li><strong>R</strong>ein</li><li><strong>S</strong>ein</li><li><strong>M</strong>élanome</li><li><strong>C</strong>ôlon-rectum</li></ul>"},{"i":"7935fdc9ecf5","n":309,"o":"309-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","q":"Comment aborder la prise en charge des métastases pulmonaires d'un cancer primitif connu ?","a":"<p>Lorsque le cancer primitif est connu :</p><ul><li>Si les images sont caractéristiques (<strong>« lâcher de ballons »</strong>, lymphangite carcinomateuse typique), le diagnostic de métastases est probable.</li><li>La <strong>preuve histologique n'est pas systématique</strong>, elle est exigée par la RCP si une modification thérapeutique est attendue ou si un phénotype/génotype particulier est suspecté.</li><li>Même pour un cancer ancien considéré comme guéri, des métastases sont possibles (> 10 ans après le traitement initial, notamment pour le sein). En cas d'atteinte pulmonaire isolée, une enquête diagnostique complète avec <strong>prélèvement histologique</strong> est requise.</li><li>Une possibilité de <strong>traitement radical</strong> peut exister, comme la chirurgie ou un traitement local (<strong>radiothérapie stéréotaxique</strong>, radiofréquence).</li></ul>"},{"i":"a1d1c5a96eeb","n":309,"o":"309-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","q":"Quelles sont les trois questions séquentielles essentielles pour la prise en charge d'une tumeur pulmonaire primitive ?","a":"<p>Les trois questions séquentielles essentielles sont :</p><ul><li>Est-ce une tumeur <strong>à petites cellules</strong> ou <strong>non à petites cellules</strong> ?</li><li>Si c'est un Carcinome Non à Petites Cellules (CNPC), est-elle <strong>résécable</strong> ou non ?</li><li>Si elle est résécable, le patient est-il <strong>opérable</strong> ?</li></ul>"},{"i":"a8b6e3eb158c","n":309,"o":"309-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","q":"Quelle est la démarche diagnostique face à des métastases pulmonaires d'un cancer primitif inconnu ?","a":"<p>La démarche diagnostique est la suivante :</p><ul><li>Réalisation d'une <strong>enquête étiologique complète</strong> (examen clinique et explorations) à la recherche d'un cancer accessible (poumon, gonades, thyroïde, sein, endomètre, prostate…).</li><li>Évoquer en première hypothèse une métastase de cancer pulmonaire chez un fumeur ou ex-fumeur.</li><li>Une <strong>TEP au <sup>18</sup>F-FDG</strong> est recommandée.</li><li>Si l'histologie pulmonaire est obtenue avant celle du primitif, elle peut orienter la recherche par le biais de l'<strong>immunohistochimie (IHC)</strong>.</li><li>Une <strong>RCP est indispensable</strong>, surtout si la recherche de primitif est négative.</li></ul>"},{"i":"d65d898abb83","n":309,"o":"309-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une tumeur du poumon primitive ou secondaire","q":"Quelle est la stratégie thérapeutique générale d'un Carcinome Non à Petites Cellules (CNPC) du poumon selon son stade ?","a":"<ul><li><strong>Stade I-II (localisé)</strong> : Si opérable, <strong>chirurgie d'exérèse</strong> avec curage ganglionnaire et potentiellement chimiothérapie adjuvante. Si inopérable, <strong>radiothérapie</strong>.</li><li><strong>Stade III (localement avancé)</strong> : <strong>Radio-chimiothérapie concomitante</strong> avec immunothérapie en maintenance.</li><li><strong>Stade IV (disséminé)</strong> : Traitement systémique exclusif, adapté au profil moléculaire (<strong>ITK</strong> si altération ciblable, <strong>immunothérapie seule</strong> si PD-L1 > 50%, <strong>chimiothérapie</strong> conventionnelle, ou <strong>combinaison chimiothérapie + immunothérapie</strong>).</li></ul>"},{"i":"2729b8e27105","n":309,"o":"309-3","u":"Etiologie","t":"Connaître les principaux facteurs de risque professionnels et environnementaux","q":"Quel est le principal facteur de risque (FdR) évitable de cancer du poumon ?","a":"<p>Le principal facteur de risque évitable de cancer du poumon est le <strong>tabac</strong>, responsable de la majorité des cas et des décès. Le tabagisme passif augmente également le risque.</p>"},{"i":"854b9fad08fb","n":309,"o":"309-3","u":"Etiologie","t":"Connaître les principaux facteurs de risque professionnels et environnementaux","q":"Comment l'exposition au radon domestique contribue-t-elle au risque de cancer du poumon ?","a":"<p>Le <strong>radon</strong> est un gaz radioactif incolore et inodore émis par les sous-sols granitiques et volcaniques. Son exposition domestique est responsable de <strong>5 à 10 %</strong> des cancers du poumon. Le seuil de l'OMS est de <strong>300 Bq/m³</strong>. La prévention repose sur l'<strong>aération</strong> régulière du logement et l'<strong>étanchéité</strong> des bâtiments.</p>"},{"i":"d466830058d4","n":309,"o":"309-3","u":"Etiologie","t":"Connaître les principaux facteurs de risque professionnels et environnementaux","q":"Quels sont les agents cancérogènes professionnels certains reconnus dans le développement du cancer du poumon ?","a":"<p>Les agents cancérogènes professionnels certains reconnus par le CIRC incluent :</p><ul><li>L'<strong>amiante</strong></li><li>L'<strong>arsenic</strong></li><li>Le <strong>bis(chlorométhyl)éther</strong></li><li>Les <strong>fumées de cadmium</strong></li><li>Le <strong>chrome hexavalent</strong></li><li>Les <strong>HAP (hydrocarbures aromatiques polycycliques)</strong></li><li>Le <strong>nickel</strong></li><li>La <strong>silice cristalline</strong> (associée à une silicose radiologique)</li><li>Les <strong>radiations ionisantes</strong> (radon professionnel)</li></ul>"},{"i":"d5cb96a5ea68","n":309,"o":"309-3","u":"Etiologie","t":"Connaître les principaux facteurs de risque professionnels et environnementaux","q":"Quel est le rôle de la pollution atmosphérique comme facteur de risque de cancer du poumon ?","a":"<p>Le rôle cancérigène de la <strong>pollution atmosphérique</strong> pour le poumon est reconnu. Les principaux polluants impliqués sont les gaz comme le <strong>SO₂, NO₂, NOₓ, O₃</strong> et les <strong>particules fines</strong>, notamment celles émises par les véhicules diesel.</p>"},{"i":"108803d8baa0","n":309,"o":"309-4","u":"Diagnostic positif","t":"Connaître les circonstances de découvertes et les manifestations cliniques des tumeurs du poumon (y compris syndromes para-néoplasiques)","q":"Quels syndromes paranéoplasiques sont évocateurs d'un cancer non à petites cellules (CNPC) du poumon ?","a":"<p>Les syndromes paranéoplasiques évocateurs d'un cancer non à petites cellules (CNPC) du poumon sont :</p><ul><li>L'<strong>hippocratisme digital</strong> (phalanges distales en baguettes de tambour, bombement des ongles dorsaux).</li><li>L'<strong>ostéoarthropathie hypertrophiante pneumique (OAHP) de Pierre-Marie-Bamberger</strong> : hippocratisme digital associé à des arthralgies distales œdémateuses et une périostose engainante en « coulée de bougie » des os longs.</li><li>La <strong>dermato-polymyosite</strong> (rash héliotrope, faiblesse musculaire proximale).</li><li>L'<strong>hypercalcémie</strong> (par sécrétion de peptide PTH-like).</li></ul>"},{"i":"2c02a4fdf766","n":309,"o":"309-4","u":"Diagnostic positif","t":"Connaître les circonstances de découvertes et les manifestations cliniques des tumeurs du poumon (y compris syndromes para-néoplasiques)","q":"Quelles sont les manifestations cliniques des métastases des tumeurs du poumon ?","a":"<p>Les manifestations cliniques des métastases des tumeurs du poumon incluent :</p><ul><li><strong>Système nerveux central (SNC)</strong> : Convulsions, signes de focalisation, hypertension intracrânienne (HTIC), compression médullaire, syndrome de la queue de cheval.</li><li><strong>Os</strong> : Douleur, fracture pathologique, tassement vertébral, hypercalcémie.</li><li><strong>Foie</strong> : Hépatomégalie, hépatalgies, perturbations du bilan biologique.</li><li><strong>Surrénales</strong> : Fréquentes mais habituellement asymptomatiques.</li><li>Moins fréquentes : <strong>Ganglionnaires</strong> superficielles, <strong>cutanées</strong> (nodules sous-cutanés), <strong>péritonéales</strong>, <strong>méningées</strong>.</li></ul>"},{"i":"683a9b26daf0","n":309,"o":"309-4","u":"Diagnostic positif","t":"Connaître les circonstances de découvertes et les manifestations cliniques des tumeurs du poumon (y compris syndromes para-néoplasiques)","q":"Quelles sont les principales manifestations cliniques respiratoires et loco-régionales des tumeurs du poumon ?","a":"<p>Les manifestations cliniques des tumeurs du poumon incluent :</p><ul><li><strong>Signes généraux</strong> : Asthénie, anorexie, amaigrissement (AEG inexpliquée).</li><li><strong>Symptômes respiratoires</strong> : Toux (récente ou modifiée), dyspnée, hémoptysie (souvent de faible abondance), expectoration purulente, pneumopathie/abcès récidivant dans un même territoire et régressant mal aux antibiotiques.</li><li><strong>Extension loco-régionale</strong> : Douleur thoracique (envahissement pariétal), épanchement pleural, syndrome de Pancoast-Tobias (plexopathie de l'apex), syndrome médiastinal (syndrome cave supérieur, dysphonie par atteinte du récurrent gauche, dysphagie, hoquet, paralysie phrénique, péricardite).</li><li><strong>Ganglions</strong> : Adénopathies axillaires, sus-claviculaires, cervicales.</li></ul>"},{"i":"6fba8864b548","n":309,"o":"309-4","u":"Diagnostic positif","t":"Connaître les circonstances de découvertes et les manifestations cliniques des tumeurs du poumon (y compris syndromes para-néoplasiques)","q":"Quels sont les principaux facteurs expliquant le diagnostic tardif des tumeurs du poumon ?","a":"<p>Les trois facteurs expliquant le diagnostic tardif du cancer du poumon sont :</p><ul><li>L'absence d'<strong>innervation nociceptive bronchopulmonaire</strong>, entraînant une absence de douleur précoce.</li><li>Des symptômes <strong>tardifs</strong>, liés à l'atteinte d'organes centraux/périphériques ou à des métastases.</li><li>Des symptômes <strong>non spécifiques</strong>.</li></ul>"},{"i":"a7285b377ff4","n":309,"o":"309-4","u":"Diagnostic positif","t":"Connaître les circonstances de découvertes et les manifestations cliniques des tumeurs du poumon (y compris syndromes para-néoplasiques)","q":"Quels syndromes paranéoplasiques sont évocateurs d'un cancer à petites cellules (CBPC) du poumon ?","a":"<p>Les syndromes paranéoplasiques évocateurs d'un cancer à petites cellules (CBPC) du poumon sont :</p><ul><li>Le <strong>syndrome de Schwartz-Bartter (SIADH)</strong> (hyponatrémie avec natriurèse conservée).</li><li>Le <strong>syndrome de Cushing</strong> (par sécrétion ectopique d'ACTH-like).</li><li>La <strong>gynécomastie</strong>.</li><li>Les <strong>syndromes neurologiques auto-immuns</strong>, tels que la pseudo-myasthénie de Lambert-Eaton, la neuropathie sensitive subaiguë de Denny-Brown et l'encéphalopathie paranéoplasique (avec anti-Hu).</li></ul>"},{"i":"063117a40914","n":309,"o":"309-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une tumeur du poumon","q":"Pourquoi la cytologie n'est-elle pas suffisante pour le diagnostic positif d'une tumeur du poumon ?","a":"<p>La cytologie n'est pas un standard car elle ne permet pas un <strong>typage complet</strong>, un <strong>bilan moléculaire fiable</strong>, ni l'établissement de l'<strong>immunohistochimie complète</strong>, nécessaires pour une prise en charge thérapeutique optimale.</p>"},{"i":"0b72912a765f","n":309,"o":"309-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une tumeur du poumon","q":"Quel est le bilan d'extension systématique à réaliser après le diagnostic histologique d'un cancer du poumon ?","a":"<ul><li><strong>TDM TAP injectée</strong> (Thorax-Abdomen-Pelvis) : pour l'extension loco-régionale (T), les adénopathies médiastinales (N), et les métastases hépatiques, surrénaliennes, ganglionnaires abdominales, osseuses (M)</li><li><strong>TDM cérébrale</strong> ou <strong>IRM cérébrale</strong> (préférable pour sa meilleure sensibilité) : systématique pour rechercher des métastases cérébrales souvent asymptomatiques</li></ul>"},{"i":"195d9c78aa1a","n":309,"o":"309-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une tumeur du poumon","q":"Dans quel cas et pour quelle raison la TEP-TDM au 18F-FDG est-elle indiquée ? Quels sont ses pièges ?","a":"<p>La TEP-TDM est indiquée <strong>uniquement si la tumeur est éligible à un traitement local</strong> (chirurgie ou radiothérapie). Elle est utilisée pour le <strong>staging N</strong> (détection d'adénopathies hypermétaboliques de taille normale) et la détection de <strong>métastases à distance</strong> (bonne VPN).</p><p>Ses pièges incluent des <strong>faux négatifs</strong> pour les nodules &lt; 1 cm ou le verre dépoli pur, et des <strong>faux positifs</strong> sur des lésions inflammatoires (infections chroniques, mycobactérioses, sarcoïdose).</p>"},{"i":"22df7860118b","n":309,"o":"309-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une tumeur du poumon","q":"Quelles sont les techniques biopsiques privilégiées selon la localisation d'une lésion pulmonaire suspecte ?","a":"<ul><li>Lésion <strong>centrale</strong> (1/3 péri-carénaire) : <strong>Fibroscopie bronchique</strong></li><li>Lésion <strong>périphérique</strong> (1/3 périphérique) : <strong>Ponction transpariétale</strong> (sous TDM ± écho-guidée) ou vidéo-thoracoscopie exploratrice</li><li>Adénopathies au contact de la trachée : <strong>EBUS</strong> (fibroscopie + aiguille)</li><li>Adénopathies médiastinales : <strong>Écho-endoscopie œsophagienne (EUS)</strong> ou <strong>Médiastinoscopie</strong></li></ul>"},{"i":"37376cb3b550","n":309,"o":"309-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une tumeur du poumon","q":"Quelles sont les 3 étapes principales de la démarche diagnostique d'une tumeur du poumon ?","a":"<ul><li><strong>Imagerie d'orientation</strong> (TDM thoracique injectée)</li><li><strong>Choix de la technique biopsique</strong> en fonction de la localisation de la lésion</li><li><strong>Preuve histologique</strong> (considérée comme le <strong>gold standard</strong> pour le diagnostic de certitude)</li></ul>"},{"i":"75c63e7f1f3a","n":309,"o":"309-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une tumeur du poumon","q":"Comment débute la démarche diagnostique devant une suspicion de tumeur du poumon ?","a":"<p>La démarche diagnostique débute par une <strong>suspicion clinico-radiologique</strong>, se manifestant par des signes tels qu'une toux récente, une hémoptysie, ou un syndrome d'altération de l'état général (AEG) chez un fumeur, ou encore la découverte fortuite d'un nodule pulmonaire.</p>"},{"i":"d09248a768eb","n":309,"o":"309-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une tumeur du poumon","q":"Quels sont les critères radiologiques (TDM) en faveur d'un nodule pulmonaire <em>hautement suspect</em> de malignité ?","a":"<ul><li>Taille <strong>supérieure à 1 cm</strong></li><li>Contours <strong>irréguliers</strong> ou <strong>spiculés</strong></li><li>Prise de contraste à la TDM</li><li>Localisation dans un <strong>lobe supérieur</strong></li><li>吸引 des structures de voisinage</li><li>Absence de calcification bénigne typique</li><li><strong>Progression rapide</strong> en taille ou en volume à l'évolution</li></ul>"},{"i":"04d1fa75b9bf","n":309,"o":"309-8","u":"Contenu multimédia","t":"Radiographie de face d’un adénocarcinome pulmonaire","q":"Comment différencier radiographiquement un adénocarcinome pulmonaire d'un carcinome épidermoïde chez un fumeur ?","a":"<p>Chez un fumeur, une <strong>opacité périphérique</strong> évoque en premier un <strong>adénocarcinome pulmonaire</strong>. En revanche, une opacité plutôt <strong>proximale ou hilaire</strong>, souvent associée à une atélectasie segmentaire, oriente plutôt vers un <strong>carcinome épidermoïde</strong>.</p>"},{"i":"49528629f2a1","n":309,"o":"309-8","u":"Contenu multimédia","t":"Radiographie de face d’un adénocarcinome pulmonaire","q":"Comment se présente radiographiquement un adénocarcinome pulmonaire typique sur une radiographie thoracique de face ?","a":"<p>Un adénocarcinome pulmonaire se manifeste typiquement par une <strong>opacité périphérique arrondie</strong>, non systématisée et dense. Ses contours sont souvent <strong>irréguliers, parfois spiculés</strong>, et il peut attirer les structures de voisinage. Il est volontiers localisé dans un <strong>lobe supérieur</strong>.</p>"},{"i":"4b9ac5108ec1","n":309,"o":"309-8","u":"Contenu multimédia","t":"Radiographie de face d’un adénocarcinome pulmonaire","q":"Quelle est la place de la radiographie thoracique dans le diagnostic d'un adénocarcinome pulmonaire et quel examen doit être réalisé en cas de doute ?","a":"<p>La radiographie thoracique (RXT) a une <strong>place marginale</strong> dans le diagnostic de cancer du poumon, bien qu'elle reste systématique. Une RXT <strong>normale n'élimine PAS</strong> le diagnostic. En cas de suspicion ou de doute, un <strong>scanner thoracique injecté</strong> prend le relais pour explorer et confirmer le diagnostic.</p>"},{"i":"9a5472483160","n":309,"o":"309-8","u":"Contenu multimédia","t":"Radiographie de face d’un adénocarcinome pulmonaire","q":"Quels sont les signes radiographiques indirects pouvant être associés à un adénocarcinome pulmonaire sur une radiographie thoracique de face ?","a":"<p>Les signes indirects pouvant être associés incluent :</p><ul><li>Des <strong>adénopathies hilaires ou médiastinales</strong>.</li><li>Un <strong>épanchement pleural</strong> (témoignant d'une extension pleurale).</li><li>Une <strong>lyse costale ou vertébrale</strong> par contiguïté.</li><li>Une <strong>ascension de coupole diaphragmatique</strong> (paralysie phrénique).</li></ul>"}]};